"""Bounded failure-only evidence for the existing installed default-auto probe.

Delivery observations run outside the hook request. Publisher fields are read
under its existing lock without waiting or changing expiry/readiness state.
The caller's client ContextVar is never attributed to a daemon worker request.
"""

from __future__ import annotations

import json
import os
import re
import threading
from collections.abc import Mapping
from contextlib import suppress
from contextvars import ContextVar, Token
from pathlib import Path
from types import TracebackType

from codex_plugin_scanner.guard.native_approval_errors import FINITE_FAILURE_CODES
from codex_plugin_scanner.guard.native_policy_snapshot_publisher import NativePolicySnapshotPublisher
from codex_plugin_scanner.guard.native_resident_client import native_resident_client_failure_code
from codex_plugin_scanner.guard.native_runtime import NativeRuntimeCapabilities, NativeRuntimeIdentity
from scripts.native_slo_contract import MAX_READINESS_P95_MS

_ACTIVE: ContextVar[DefaultAutoFailureCapture | None] = ContextVar("default_auto_failure_capture", default=None)
_HARNESS = frozenset(
    {
        "antigravity",
        "claude-code",
        "cline",
        "codex",
        "copilot",
        "cursor",
        "gemini",
        "grok",
        "hermes",
        "kimi",
        "omp",
        "openclaw",
        "opencode",
        "paseo",
        "pi",
        "zcode",
    }
)
_CODES = FINITE_FAILURE_CODES | frozenset(
    {
        "guardconfigsourceerror",
        "oserror",
        "runtimeerror",
        "typeerror",
        "valueerror",
        "attributeerror",
        "operationalerror",
        "databaseerror",
        "native_policy_snapshot_ack_invalid",
        "native_policy_snapshot_ack_mismatch",
        "native_policy_snapshot_expired",
        "native_policy_snapshot_integrity_key_unavailable",
        "native_policy_snapshot_native_disabled",
        "native_policy_snapshot_protocol_unsupported",
        "native_policy_snapshot_publish_failed",
        "native_policy_snapshot_resident_changed",
        "native_policy_snapshot_runtime_unavailable",
        "native_policy_snapshot_workspace_capacity",
        "native_client_containment_failed",
        "native_client_timed_out",
        "native_client_output_limit_exceeded",
        "native_client_status_missing",
        "native_client_exit_nonzero",
        "native_client_output_missing",
        "native_client_process_failed",
        "native_client_launcher_failed",
        "native_client_request_invalid",
        "native_client_start_failed",
        "native_client_stdin_unavailable",
        "native_client_stream_failed",
        "native_exact_safe_command",
        "native_command_control_authority_block",
        "native_command_control_mutation_in_progress",
        "native_policy_warning",
        "native_policy_block",
        "native_hook_unavailable",
        "native_post_tool_unavailable",
        "native_pre_tool_unavailable",
        "native_degraded_emergency_safe",
        "output_secret_match",
        "output_clean",
    }
)
_ROUTES = frozenset({"native_resident", "native_oneshot", "native_fail_safe", "native_degraded", "python_semantic"})
_RECEIPTS = frozenset(
    {
        "receipt_accepted",
        "receipt_processed",
        "receipt_deduped",
        "receipt_dropped",
        "receipt_failures",
        "receipt_durable_pending",
    }
)


def _code(value: object) -> str | None:
    return value if type(value) is str and value in _CODES else None if value is None else "other"


def _integer(value: object) -> int | None:
    return value if type(value) is int and 0 <= value <= 2**63 - 1 else None


def _choice(value: object, choices: set[str] | frozenset[str]) -> str:
    return value if type(value) is str and value in choices else "other"


def _hex(value: object, length: int) -> str | None:
    return value if type(value) is str and re.fullmatch(f"[0-9a-f]{{{length}}}", value) else None


def _counts(value: object, fields: frozenset[str]) -> dict[str, int]:
    if type(value) is not dict:
        return {}
    return {field: count for field in fields if (count := _integer(value.get(field))) is not None}


def _publisher(daemon: object) -> object:
    return getattr(getattr(getattr(daemon, "_server", None), "hook_worker", None), "policy_snapshot_publisher", None)


def _publisher_state(publisher: object) -> dict[str, object]:
    if type(publisher) is not NativePolicySnapshotPublisher:
        return {"available": False}
    condition = publisher._condition
    if not condition.acquire(blocking=False):
        return {"available": False, "busy": True}
    try:
        snapshot = publisher._snapshot
        return {
            "available": True,
            "epoch": _integer(publisher._epoch),
            "snapshot_generation": _integer(snapshot.get("generation")) if type(snapshot) is dict else None,
            "ack_recorded": publisher._acked is True,
            "closed": publisher._closed is True,
            "last_error": _code(publisher._last_error),
        }
    finally:
        condition.release()


def _client_context() -> dict[str, object]:
    return {
        "scope": "probe_context_only",
        "daemon_worker_attribution": False,
        "code": _code(native_resident_client_failure_code()),
    }


def _failure_category(error: BaseException) -> str:
    return (
        type(error).__name__
        if type(error) in {RuntimeError, AssertionError, ValueError, TypeError, OSError, TimeoutError}
        else "other"
    )


class DefaultAutoFailureCapture:
    """Own one probe invocation; write separate evidence only on original failure."""

    def __init__(self, success_path: Path | None) -> None:
        self._path = success_path.with_name(success_path.stem + "-failure.json") if success_path is not None else None
        self._owner = threading.get_ident()
        self._token: Token[DefaultAutoFailureCapture | None] | None = None
        self._publisher: object = None
        self._corpus_active = False
        self._corpus_observed = False
        self._identity: dict[str, object] = {}
        self._deliveries: list[dict[str, object]] = []
        self._corpus: dict[str, object] = {}
        self._smoke_publication: dict[str, object] = {}
        self._incomplete = False
        self._primary_failure: str | None = None
        self._expected_sha = _hex(os.environ.get("SOURCE_SHA"), 40)

    def __enter__(self) -> DefaultAutoFailureCapture:
        self._token = _ACTIVE.set(self)
        return self

    def bind_identity(self, identity: NativeRuntimeIdentity, capabilities: NativeRuntimeCapabilities) -> None:
        try:
            self._identity = {
                "build_sha": _hex(capabilities.build_sha, 40),
                "runtime_sha256": _hex(identity.sha256, 64),
                "rule_digest": _hex(capabilities.rule_digest, 64),
                "runtime_size": _integer(identity.size),
                "protocol_version": _integer(capabilities.protocol_version),
                "target": _choice(
                    capabilities.target,
                    {"x86_64-windows", "x86_64-linux", "aarch64-linux", "x86_64-macos", "aarch64-macos"},
                ),
            }
        except Exception:
            self._incomplete = True

    def bind_corpus(self, daemon: object) -> None:
        self._publisher = _publisher(daemon)
        self._corpus_active = True

    def _owned_state(self, daemon: object) -> dict[str, object]:
        if not self._corpus_active or _publisher(daemon) is not self._publisher:
            return {"available": False, "owned_publisher_changed_or_retired": True}
        return _publisher_state(self._publisher)

    def delivery(self, daemon: object, harness: str, event: str, response: object) -> None:
        if not self._corpus_active:
            return
        if len(self._deliveries) == 21:
            self._incomplete = True
            return
        value = response if type(response) is dict else {}
        self._deliveries.append(
            {
                "index": len(self._deliveries),
                "harness": _choice(harness, _HARNESS),
                "event": _choice(event, {"PreToolUse", "PostToolUse"}),
                "response_present": type(response) is dict,
                "reason_code": _code(value.get("reason_code")),
                "decision": _choice(value.get("decision"), {"allow", "deny", "block", "review", "ask"}),
                "publisher_after_delivery": self._owned_state(daemon),
                "publisher_attribution": "state_observed_after_delivery_not_request_cause",
            }
        )

    def observe_corpus(self, daemon: object, worker_stats: object) -> None:
        if not self._corpus_active or self._corpus_observed:
            return
        stats = worker_stats if isinstance(worker_stats, Mapping) else {}
        self._corpus = {
            "capture_boundary": "before_mode_changes_and_daemon_cleanup",
            "routes": _counts(stats.get("routes"), _ROUTES),
            "publisher": self._owned_state(daemon),
            "client_context": _client_context(),
        }
        self._corpus_observed = True

    def end_corpus(self, daemon: object, worker_stats: object, evidence_stats: object) -> None:
        if not self._corpus_observed:
            self.observe_corpus(daemon, worker_stats)
            self._corpus["capture_boundary"] = "early_exit_before_daemon_cleanup"
        self._corpus["receipt_counts"] = _counts(evidence_stats, _RECEIPTS)
        self._corpus_active = False
        self._publisher = None

    def corpus_failure(self, error: BaseException) -> None:
        if self._corpus_active:
            self._primary_failure = _failure_category(error)

    def smoke_publication(self, report: dict[str, object]) -> None:
        self._smoke_publication = report

    def __exit__(
        self, kind: type[BaseException] | None, error: BaseException | None, trace: TracebackType | None
    ) -> None:
        del kind, trace
        try:
            if error is not None and self._path is not None:
                # Nothing in diagnostic construction or persistence may replace
                # the original exception or turn a failed gate into success.
                with suppress(Exception):
                    self._write_failure(error)
        finally:
            self._corpus_active = False
            self._publisher = None
            if self._token is not None:
                _ACTIVE.reset(self._token)
                self._token = None

    def _write_failure(self, error: BaseException) -> None:
        report: dict[str, object] = {
            "schema": "hol-guard.native-default-auto-failure.v1",
            "passed": False,
            "qualification": False,
            "expected_build_sha": self._expected_sha,
            "installed_identity": self._identity,
            "required_native_decisions": 21,
            "allowed_fail_safe_decisions": 0,
            "readiness_budget_ms": MAX_READINESS_P95_MS,
            "original_failure_category": _failure_category(error),
            "primary_failure_before_cleanup": self._primary_failure,
        }
        try:
            detailed = {
                **report,
                "deliveries": self._deliveries,
                "corpus": self._corpus,
                "smoke_publication": self._smoke_publication,
                "detail_incomplete": self._incomplete,
            }
            encoded = json.dumps(detailed, sort_keys=True, separators=(",", ":"))
            if len(encoded.encode("utf-8")) > 32 * 1024:
                raise ValueError("diagnostic_bound_exceeded")
        except Exception:
            encoded = json.dumps({**report, "detail_incomplete": True}, sort_keys=True)
        assert self._path is not None
        with self._path.open("x", encoding="utf-8") as handle:
            handle.write(encoded + "\n")


def _observe(method: str, *args: object) -> None:
    capture = _ACTIVE.get()
    if capture is None or threading.get_ident() != capture._owner:
        return
    try:
        getattr(capture, method)(*args)
    except Exception:
        capture._incomplete = True


def bind_corpus(daemon: object) -> None:
    _observe("bind_corpus", daemon)


def observe_delivery(daemon: object, harness: str, event: str, response: object) -> None:
    _observe("delivery", daemon, harness, event, response)


def observe_corpus(daemon: object, worker_stats: object) -> None:
    _observe("observe_corpus", daemon, worker_stats)


def end_corpus(daemon: object, worker_stats: object, evidence_stats: object) -> None:
    _observe("end_corpus", daemon, worker_stats, evidence_stats)


def observe_corpus_failure(error: BaseException) -> None:
    _observe("corpus_failure", error)

//! Compile authenticated controls once against the exact packaged catalog.

use std::collections::{BTreeMap, BTreeSet};
use std::sync::Arc;
use std::time::Instant;

use guard_contracts::{
    NativeCommandControlBindingV1, NativeCommandObservationBatchV1, NativeCommandObservationsV1,
    NativeCommandReceiptBindingV1, PreToolResultV1, NATIVE_COMMAND_OBSERVATIONS_SCHEMA,
    NATIVE_COMMAND_RECEIPT_BINDING_SCHEMA,
};

use crate::native_command_control_projection::project_validated_layer;
use crate::native_command_program::{
    digest_value, packaged_command_program, NativeCommandProgram, ProgramRule,
};
use crate::CanonicalCommandV1;

#[derive(Debug)]
pub struct CompiledNativeCommandControls {
    program: Arc<NativeCommandProgram>,
    binding: NativeCommandControlBindingV1,
    active_extensions: BTreeSet<String>,
    blocked_extensions: BTreeSet<String>,
    blocked_permissions: BTreeSet<String>,
    explicitly_enabled_permissions: BTreeSet<String>,
    global_block: bool,
    rule_indices: BTreeMap<String, usize>,
}

impl CompiledNativeCommandControls {
    pub fn new(binding: &NativeCommandControlBindingV1) -> Result<Self, &'static str> {
        Self::for_program(binding, packaged_command_program()?)
    }

    // Production always supplies the packaged, attested program through new().
    // The crate-local seam also lets diagnostic tests vary real compiled
    // catalogs without duplicating any control admission or evaluation logic.
    pub(crate) fn for_program(
        binding: &NativeCommandControlBindingV1,
        program: Arc<NativeCommandProgram>,
    ) -> Result<Self, &'static str> {
        binding.validate()?;
        if binding.program_digest != program.program_digest
            || binding.catalog_digest != program.catalog_digest
            || binding.trust_digest != program.trust_digest
        {
            return Err("native_command_program_binding_mismatch");
        }
        let extension_indices: BTreeMap<_, _> = program
            .extensions
            .iter()
            .enumerate()
            .map(|(index, extension)| (extension.extension_id.as_str(), index))
            .collect();
        let permissions: BTreeMap<_, _> = program
            .extensions
            .iter()
            .flat_map(|extension| {
                extension.permissions.iter().map(move |permission| {
                    (permission.permission_id.as_str(), (extension, permission))
                })
            })
            .collect();
        let mut composed = BTreeMap::<(&str, &str), bool>::new();
        let mut locally_enabled = BTreeSet::new();
        let mut global_block = binding.health != "protected";
        for layer in &binding.layers {
            global_block |= layer.global_lockdown;
            for ((target_kind, target_id), disabled) in project_validated_layer(layer)? {
                let is_extension = target_kind == "extension";
                if (is_extension && !extension_indices.contains_key(target_id))
                    || (!is_extension && !permissions.contains_key(target_id))
                {
                    return Err("native_command_control_target_unknown");
                }
                composed
                    .entry((target_kind, target_id))
                    .and_modify(|previous| *previous |= disabled)
                    .or_insert(disabled);
                if is_extension && layer.kind == "local-admin" && !disabled {
                    locally_enabled.insert(target_id);
                }
            }
        }
        let mut active_extensions = BTreeSet::new();
        let mut blocked_extensions = BTreeSet::new();
        for extension in &program.extensions {
            let disabled =
                composed.get(&("extension", extension.extension_id.as_str())) == Some(&true);
            let active = extension.required
                || extension.trust_class != "external"
                || (locally_enabled.contains(extension.extension_id.as_str()) && !disabled);
            if active {
                active_extensions.insert(extension.extension_id.clone());
            }
            let mut pending = vec![extension.extension_id.as_str()];
            let mut visited = BTreeSet::new();
            while let Some(id) = pending.pop() {
                if !visited.insert(id) {
                    continue;
                }
                if composed.get(&("extension", id)) == Some(&true) {
                    blocked_extensions.insert(extension.extension_id.clone());
                }
                let index = *extension_indices
                    .get(id)
                    .ok_or("native_command_extension_dependency_unknown")?;
                pending.extend(
                    program.extensions[index]
                        .dependencies
                        .iter()
                        .map(String::as_str),
                );
            }
        }
        let mut blocked_permissions = BTreeSet::new();
        let mut explicitly_enabled_permissions = BTreeSet::new();
        for (id, (_, permission)) in &permissions {
            if binding.health == "protected"
                && permission.configurable
                && composed.get(&("permission", id)) == Some(&false)
            {
                explicitly_enabled_permissions.insert((*id).to_owned());
            }
            let mut pending = vec![*id];
            let mut visited = BTreeSet::new();
            while let Some(current) = pending.pop() {
                if !visited.insert(current) {
                    continue;
                }
                let (owner, dependent) = permissions
                    .get(current)
                    .ok_or("native_command_permission_dependency_unknown")?;
                if composed.get(&("permission", current)) == Some(&true)
                    || blocked_extensions.contains(&owner.extension_id)
                {
                    blocked_permissions.insert((*id).to_owned());
                }
                pending.extend(
                    dependent
                        .dependencies
                        .iter()
                        .chain(&dependent.implied_permissions)
                        .map(String::as_str),
                );
            }
        }
        let rule_indices = program
            .rules
            .iter()
            .enumerate()
            .map(|(index, rule)| (rule.rule_id.clone(), index))
            .collect();
        Ok(Self {
            program,
            binding: binding.clone(),
            active_extensions,
            blocked_extensions,
            blocked_permissions,
            explicitly_enabled_permissions,
            global_block,
            rule_indices,
        })
    }

    pub fn apply(
        &self,
        command: &CanonicalCommandV1,
        mut result: PreToolResultV1,
        deadline: Option<Instant>,
    ) -> PreToolResultV1 {
        let batch = match self
            .program
            .observe(command, &self.active_extensions, deadline)
        {
            Ok(batch) => batch,
            Err(_) => {
                strengthen(
                    &mut result,
                    "block",
                    "native_command_extension_evaluation_failed",
                );
                NativeCommandObservationBatchV1 {
                    evaluation_error: Some("native_command_evaluation_failed".to_owned()),
                    ..Default::default()
                }
            }
        };
        let mut floor = if self.global_block { "block" } else { "allow" };
        let mut reason = if self.global_block {
            "native_command_control_authority_block"
        } else {
            "native_command_extension_review"
        };
        for observation in &batch.observations {
            if !observation.uncertainty_reasons.is_empty() {
                floor = "block";
                reason = "native_command_extension_uncertain";
            }
            if self.blocked_extensions.contains(&observation.extension_id) {
                floor = "block";
                reason = "native_command_extension_disabled";
            }
            if observation.effective_segment_indexes.is_empty() {
                continue;
            }
            let Some(index) = self.rule_indices.get(&observation.rule_id) else {
                floor = "block";
                reason = "native_command_extension_identity_invalid";
                continue;
            };
            let rule = &self.program.rules[*index];
            if self.blocked_permissions.contains(&rule.permission_id) {
                floor = "block";
                reason = "native_command_permission_disabled";
            }
            if !self
                .explicitly_enabled_permissions
                .contains(&rule.permission_id)
            {
                let candidate =
                    rule_floor(rule, self.program.extensions[rule.extension_index].required);
                if rank(candidate) > rank(floor) {
                    floor = candidate;
                }
            }
        }
        for observation in &batch.permission_observations {
            if !observation.uncertainty_reasons.is_empty() {
                floor = "block";
                reason = "native_command_extension_uncertain";
            }
            if self.blocked_extensions.contains(&observation.extension_id)
                || self
                    .blocked_permissions
                    .contains(&observation.permission_id)
            {
                floor = "block";
                reason = "native_command_permission_disabled";
            }
        }
        let observations_digest =
            match digest_value(b"hol-guard.native-command-observations.v1\0", &batch) {
                Ok(digest) => digest,
                Err(_) => {
                    strengthen(
                        &mut result,
                        "block",
                        "native_command_extension_evaluation_failed",
                    );
                    return result;
                }
            };
        let binding = NativeCommandReceiptBindingV1 {
            schema: NATIVE_COMMAND_RECEIPT_BINDING_SCHEMA.to_owned(),
            program_digest: self.binding.program_digest.clone(),
            catalog_digest: self.binding.catalog_digest.clone(),
            trust_digest: self.binding.trust_digest.clone(),
            control_revision: self.binding.revision,
            managed_control_revision: self.binding.managed_revision,
            control_effective_digest: self.binding.effective_digest.clone(),
            observations_digest,
            observation_count: batch.observations.len() + batch.permission_observations.len(),
            uncertainty_count: batch
                .observations
                .iter()
                .filter(|observation| !observation.uncertainty_reasons.is_empty())
                .count()
                + batch
                    .permission_observations
                    .iter()
                    .filter(|observation| !observation.uncertainty_reasons.is_empty())
                    .count()
                + usize::from(batch.evaluation_error.is_some()),
        };
        result.command_extensions = Some(NativeCommandObservationsV1 {
            schema: NATIVE_COMMAND_OBSERVATIONS_SCHEMA.to_owned(),
            binding,
            observations: batch.observations,
            permission_observations: batch.permission_observations,
            evaluation_error: batch.evaluation_error,
        });
        strengthen(&mut result, floor, reason);
        result
    }
}

fn rule_floor(rule: &ProgramRule, required: bool) -> &'static str {
    if rule.is_compatibility_attribution_only() {
        return "allow";
    }
    if required {
        return if rule.severity == "critical" {
            "block"
        } else {
            "review"
        };
    }
    match rule.default_mode.as_str() {
        "disabled" => "allow",
        "monitor" => "warn",
        "review" | "required" => "review",
        _ => "block",
    }
}

fn rank(action: &str) -> u8 {
    match action {
        "allow" => 0,
        "warn" => 1,
        "review" => 2,
        "require-reapproval" => 3,
        "sandbox-required" => 4,
        _ => 5,
    }
}

fn strengthen(result: &mut PreToolResultV1, action: &str, reason: &str) {
    if rank(action) > rank(&result.minimum_action) {
        result.minimum_action = action.to_owned();
        result.policy_action = action.to_owned();
        result.decision = if matches!(action, "allow" | "warn") {
            "allow"
        } else {
            "deny"
        }
        .to_owned();
        result.explicitly_benign = action == "allow";
        result.reason_code = reason.to_owned();
        result.reason = "HOL Guard requires the native command extension policy before this action can execute.".to_owned();
    }
}

use crate::{parse_command, CanonicalCommandV1, CommandModelRequestV1};
use guard_secure_fs::sensitive_path_family;
use serde::{Deserialize, Serialize};
use std::path::Path;

mod search;

use search::safe_search_arguments;

pub mod generic;

pub use generic::evaluate_pre_tool_envelope;
pub use generic::evaluate_pre_tool_envelope_with_extensions;
pub use generic::evaluate_pre_tool_envelope_with_extensions_and_scope;

fn executable_basename(executable: &str) -> &str {
    executable.rsplit(['/', '\\']).next().unwrap_or(executable)
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PreToolDecisionV1 {
    pub decision: String,
    pub minimum_action: String,
    pub reason_code: String,
    pub reason: String,
    pub explicitly_benign: bool,
    pub command_model: CanonicalCommandV1,
}

fn pretool_decision(
    command_model: CanonicalCommandV1,
    minimum_action: &str,
    reason_code: &str,
    reason: &str,
) -> PreToolDecisionV1 {
    let explicitly_benign = minimum_action == "allow";
    PreToolDecisionV1 {
        decision: if explicitly_benign {
            "allow".to_owned()
        } else {
            "deny".to_owned()
        },
        minimum_action: minimum_action.to_owned(),
        reason_code: reason_code.to_owned(),
        reason: reason.to_owned(),
        explicitly_benign,
        command_model,
    }
}

pub(super) fn normalized_haystack(value: &str) -> String {
    value.to_ascii_lowercase().replace('\\', "/")
}

pub(super) fn sensitive_command(value: &str) -> bool {
    let lowered = normalized_haystack(value);
    let needles = [
        "/.ssh/",
        "~/.ssh",
        "/.aws/credentials",
        "~/.aws/credentials",
        "/.docker/config.json",
        "~/.docker/config.json",
        "/.kube/config",
        "~/.kube/config",
        "/.git-credentials",
        "~/.git-credentials",
        "/.npmrc",
        "~/.npmrc",
        "/.pypirc",
        "~/.pypirc",
        "/.netrc",
        "~/.netrc",
        "/.env",
        "~/.env",
        "id_rsa",
        "id_ed25519",
        "aws_secret_access_key",
        "private_key",
        ".env",
        "api key",
        "api_key",
        "api-key",
        "password",
        "secret",
    ];
    needles.iter().any(|needle| lowered.contains(needle))
        || lowered.contains("printenv")
        || lowered.contains("os.environ")
        || lowered.contains("process.env")
}

fn sensitive_path_argument(value: &str) -> bool {
    let normalized = normalized_haystack(value);
    let candidates = [
        normalized.as_str(),
        normalized.split_once('=').map_or("", |(_, tail)| tail),
        normalized.rsplit_once(':').map_or("", |(_, tail)| tail),
    ];
    candidates.iter().any(|candidate| {
        let relative = candidate.trim_start_matches("./");
        sensitive_path_family(Path::new(relative)).is_some()
            || relative == ".git/config"
            || relative.ends_with("/.git/config")
    })
}

fn has_argument(arguments: &[String], exact: &[&str], prefixes: &[&str]) -> bool {
    arguments.iter().any(|argument| {
        exact.contains(&argument.as_str())
            || prefixes.iter().any(|prefix| argument.starts_with(prefix))
    })
}

fn safe_git_arguments(arguments: &[String], allow_helper_context: bool) -> bool {
    let Some(subcommand) = arguments.first().map(String::as_str) else {
        return false;
    };
    if !matches!(
        subcommand,
        "status" | "diff" | "log" | "show" | "rev-parse" | "ls-files"
    ) {
        return false;
    }
    let option_end = arguments
        .iter()
        .position(|argument| argument == "--")
        .unwrap_or(arguments.len());
    let active_options = &arguments[1..option_end];
    if !allow_helper_context
        && matches!(subcommand, "diff" | "log" | "show")
        && !(active_options
            .iter()
            .any(|argument| argument == "--no-ext-diff")
            && active_options
                .iter()
                .any(|argument| argument == "--no-textconv"))
    {
        return false;
    }
    !has_argument(
        active_options,
        &["--ext-diff", "--textconv", "--output", "-o"],
        &["--output=", "--exec-path="],
    )
}

fn git_helper_context_required(model: &CanonicalCommandV1) -> bool {
    exact_safe_command(model, true)
        && model.segments.iter().any(|segment| {
            segment.executable.as_deref().is_some_and(|executable| {
                executable_basename(executable) == "git"
                    && segment.arguments.first().is_some_and(|subcommand| {
                        let option_end = segment
                            .arguments
                            .iter()
                            .position(|argument| argument == "--")
                            .unwrap_or(segment.arguments.len());
                        let active_options = &segment.arguments[1..option_end];
                        matches!(subcommand.as_str(), "diff" | "log" | "show")
                            && !(active_options
                                .iter()
                                .any(|argument| argument == "--no-ext-diff")
                                && active_options
                                    .iter()
                                    .any(|argument| argument == "--no-textconv"))
                    })
            })
        })
}

fn destructive_command(value: &str) -> bool {
    let lowered = normalized_haystack(value);
    let rm_force = lowered.contains("rm -rf") || lowered.contains("rm -fr");
    let rm_root = [" /", " -- /", " $home", " ~", " --/"]
        .iter()
        .any(|needle| lowered.contains(needle));
    if rm_force && rm_root {
        return true;
    }
    let basename_tokens: Vec<&str> = lowered
        .split(|character: char| character.is_ascii_whitespace() || character == '=')
        .filter(|token| !token.is_empty())
        .collect();
    basename_tokens.iter().any(|token| {
        matches!(
            executable_basename(token),
            "shred" | "mkfs" | "mkfs.ext4" | "shutdown" | "reboot" | "wipefs"
        )
    }) || lowered.contains(" of=/dev/")
        || lowered.contains("of=/dev/")
}

fn exfiltration_command(value: &str) -> bool {
    let lowered = normalized_haystack(value);
    let network = ["curl", "wget", "nc ", "netcat", "scp ", "rsync "];
    let upload = [
        " -d ",
        " --data",
        " --upload-file",
        " -t ",
        "@-",
        "@~",
        "@/",
    ];
    network.iter().any(|needle| lowered.contains(needle))
        && upload.iter().any(|needle| lowered.contains(needle))
}

fn exact_safe_command(model: &CanonicalCommandV1, allow_git_helper_context: bool) -> bool {
    if model.confidence != "exact" || model.path_overridden || model.segments.is_empty() {
        return false;
    }
    model.segments.iter().all(|segment| {
        let Some(executable) = segment.executable.as_deref() else {
            return false;
        };
        let basename = executable_basename(executable);
        if sensitive_command(&segment.text)
            || (!matches!(basename, "rg" | "grep")
                && segment
                    .arguments
                    .iter()
                    .any(|argument| sensitive_path_argument(argument)))
            || !segment.environment_names.is_empty()
            || executable.contains(['/', '\\'])
        {
            return false;
        }
        match basename {
            "pwd" | "true" | "echo" | "printf" | "which" | "whoami" | "uname" | "stat" => true,
            "git" => safe_git_arguments(&segment.arguments, allow_git_helper_context),
            "rg" | "grep" => safe_search_arguments(basename, &segment.arguments),
            _ => false,
        }
    })
}

pub fn evaluate_pre_tool(request: &CommandModelRequestV1) -> Result<PreToolDecisionV1, String> {
    let model = parse_command(request)?;
    let normalized = model.normalized_text.as_str();
    if destructive_command(normalized) {
        return Ok(pretool_decision(
            model,
            "block",
            "native_destructive_command",
            "HOL Guard blocked a destructive command before execution.",
        ));
    }
    if sensitive_command(normalized) && exfiltration_command(normalized) {
        return Ok(pretool_decision(
            model,
            "block",
            "native_secret_exfiltration",
            "HOL Guard blocked a command that combines sensitive data access with network transfer.",
        ));
    }
    if exact_safe_command(&model, false) {
        return Ok(pretool_decision(
            model,
            "allow",
            "native_exact_safe_command",
            "The Rust command authority proved this bounded command explicitly benign.",
        ));
    }
    if sensitive_command(normalized) {
        return Ok(pretool_decision(
            model,
            "review",
            "native_sensitive_access_review",
            "HOL Guard requires review before this command can access sensitive local data.",
        ));
    }
    if model.path_overridden {
        return Ok(pretool_decision(
            model,
            "review",
            "native_path_override_review",
            "HOL Guard requires review because this command overrides executable resolution.",
        ));
    }
    if git_helper_context_required(&model) {
        return Ok(pretool_decision(
            model,
            "review",
            "native_git_helper_context_review",
            "HOL Guard is checking repository Git-helper configuration before allowing this read-only command.",
        ));
    }
    Ok(pretool_decision(
        model,
        "review",
        "native_command_review_required",
        "HOL Guard requires review because the Rust authority could not prove this command explicitly benign.",
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn request(command: &str) -> CommandModelRequestV1 {
        CommandModelRequestV1 {
            command: command.to_owned(),
            dialect: "posix".to_owned(),
            transport: "shell_string".to_owned(),
            extraction_provenance: "guard-shell".to_owned(),
        }
    }

    #[test]
    fn blocks_destructive_and_device_commands() {
        for command in [
            "rm -rf /",
            "rm -rf -- /",
            "shred ~/.ssh/id_ed25519",
            "dd if=/dev/zero of=/dev/sda",
            "mkfs.ext4 /dev/sda1",
            "shutdown -h now",
            "reboot",
            "wipefs -a /dev/sda",
        ] {
            let decision = evaluate_pre_tool(&request(command)).unwrap();
            assert_eq!(decision.decision, "deny", "{command}");
            assert_eq!(decision.minimum_action, "block", "{command}");
        }
    }

    #[test]
    fn reviews_home_relative_secret_paths() {
        let decision = evaluate_pre_tool(&request("cat ~/.npmrc")).unwrap();
        assert_eq!(decision.decision, "deny");
        assert_eq!(decision.minimum_action, "review");
        assert_eq!(decision.reason_code, "native_sensitive_access_review");
    }

    #[test]
    fn reviews_dotenv_family_shell_reads() {
        for command in [
            "cat .env",
            "cat .env.synthetic",
            "cat /workspace/.env.local",
        ] {
            let decision = evaluate_pre_tool(&request(command)).unwrap();
            assert_eq!(decision.decision, "deny", "{command}");
            assert_eq!(decision.minimum_action, "review", "{command}");
            assert_eq!(
                decision.reason_code, "native_sensitive_access_review",
                "{command}"
            );
        }
    }

    #[test]
    fn allows_bounded_exact_commands() {
        for command in [
            "pwd",
            "whoami",
            "uname -a",
            "git status --short",
            "git rev-parse --show-toplevel",
            "git diff --no-ext-diff --no-textconv --check",
            "rg -n authority src",
            "rg -g*.ts authority src",
            "rg --glob '*.{ts,tsx}' authority src",
            "rg --line-number --color=never authority src",
            "grep -n authority README.md",
            "grep --line-number --color=never authority README.md",
            "grep -eerror README.md",
            "grep -e 'terraform.tfvars' README.md",
            "grep -d skip authority README.md",
            "stat README.md",
        ] {
            let decision = evaluate_pre_tool(&request(command)).unwrap();
            assert_eq!(decision.decision, "allow", "{command}");
            assert!(decision.explicitly_benign, "{command}");
        }
    }

    #[test]
    fn reviews_only_materially_risky_variants_of_safe_commands() {
        for command in [
            "rg --pre /opt/guard-test/payload authority src",
            "rg --hostname-bin=/opt/guard-test/payload --hyperlink-format='file://{host}{path}' TOKEN src",
            "rg --hidden authority .",
            "rg -uuu authority .",
            "rg -L authority .",
            "rg --no-ignore-files authority .",
            "rg --glob '*.env' TOKEN .",
            "rg --glob '*.{env,ts}' TOKEN .",
            "rg --glob 'nested/*.env' TOKEN .",
            "rg --glob 'nested/[.]env' TOKEN .",
            r"rg --glob 'nested/[\.]env' TOKEN .",
            "rg --glob 'nested/{safe,.env}' TOKEN .",
            "rg TOKEN .env.local",
            "rg -e '.env.local' src",
            "grep -r password .",
            "rg id_rsa /home",
            "rg --glob 'nested/[.]env.local' TOKEN .",
            "rg --glob 'nested/[.]env.production' TOKEN .",
            "rg --glob 'nested/[.]e[n]v.production' TOKEN .",
            "rg --glob 'nested/[.]e*v.production' TOKEN .",
            "rg --glob 'my-private-[k]ey-prod.pem' TOKEN .",
            "rg --glob 'my-private-[ak]ey-prod.pem' TOKEN .",
            "rg --glob 'my-pr[i]vate-[k]ey-prod.pem' TOKEN .",
            "rg --type-add 'secret:.env' -tsecret TOKEN .",
            "rg TOKEN .aws/config",
            "rg TOKEN terraform.tfvars",
            "rg TOKEN wallet.key",
            "rg TOKEN .gnupg/private-keys-v1.d/key",
            "rg authority .env",
            "grep authority .npmrc",
            "grep TOKEN .*",
            "grep TOKEN '.[a-z]*'",
            "grep TOKEN nested/.*",
            "grep -R authority .",
            "grep -d recurse TOKEN .",
            "grep --directories=recurse TOKEN .",
            "grep --recursiv TOKEN .",
            "grep --direct=recurse TOKEN .",
            "rg --hidd TOKEN .",
            "rg --globx '*.ts' TOKEN .",
            "/opt/guard-test/rg authority src",
            "FOO=bar git status --short",
            "GIT_EXTERNAL_DIFF=/opt/guard-test/payload git diff --ext-diff README.md",
            "git diff --output=/opt/guard-test/diff README.md",
            "git log -1 --output=/opt/guard-test/log",
            "git diff --check",
            "git log -1",
            "git show HEAD",
            "git show HEAD:.env",
            "git show HEAD:.git/config",
        ] {
            let decision = evaluate_pre_tool(&request(command)).unwrap();
            assert_eq!(decision.decision, "deny", "{command}");
            assert_eq!(decision.minimum_action, "review", "{command}");
            assert!(!decision.explicitly_benign, "{command}");
        }
    }

    #[test]
    fn defers_only_exact_safe_git_helper_context() {
        let contextual = evaluate_pre_tool(&request("git diff --check")).unwrap();
        assert_eq!(contextual.reason_code, "native_git_helper_context_review");

        let unsafe_output =
            evaluate_pre_tool(&request("git diff --output=/tmp/diff README.md")).unwrap();
        assert_eq!(unsafe_output.reason_code, "native_command_review_required");

        let option_shaped_paths =
            evaluate_pre_tool(&request("git diff -- --no-ext-diff --no-textconv")).unwrap();
        assert_eq!(
            option_shaped_paths.reason_code,
            "native_git_helper_context_review"
        );
    }

    #[test]
    fn denies_uncertain_or_networked_commands() {
        for command in [
            "echo $(whoami)",
            "pwd && rm -rf /",
            "python -c 'print(1)'",
            "git push origin main",
            "PATH=/tmp:$PATH ls",
        ] {
            let decision = evaluate_pre_tool(&request(command)).unwrap();
            assert_eq!(decision.decision, "deny", "{command}");
            assert_ne!(decision.minimum_action, "allow", "{command}");
        }
    }
}

