        let _ = std::io::stdin().read_exact(&mut byte);
    }
}

fn accept_bounded(listener: &TcpListener) -> TcpStream {
    listener.set_nonblocking(true).unwrap();
    let deadline = Instant::now() + Duration::from_secs(2);
    loop {
        match listener.accept() {
            Ok((stream, _)) => {
                // BSD sockets inherit the listener's nonblocking mode. The
                // exchange below uses blocking I/O with bounded timeouts.
                stream.set_nonblocking(false).unwrap();
                stream
                    .set_read_timeout(Some(Duration::from_secs(2)))
                    .unwrap();
                stream
                    .set_write_timeout(Some(Duration::from_secs(2)))
                    .unwrap();
                return stream;
            }
            Err(error)
                if error.kind() == std::io::ErrorKind::WouldBlock && Instant::now() < deadline =>
            {
                thread::sleep(Duration::from_millis(1));
            }
            Err(error) => panic!("managed retry fixture did not receive a connection: {error}"),
        }
    }
}

#[derive(Clone, Copy, Debug)]
enum FailurePhase {
    Authentication,
    CommittedResponse,
}

#[test]
fn managed_restart_preserves_fatal_exchange_failures_after_owner_exit() {
    for phase in [
        FailurePhase::Authentication,
        FailurePhase::CommittedResponse,
    ] {
        for owner_exits in [false, true] {
            let home = TestHome::new();
            let digest = runtime_digest().unwrap();
            let scope = state_scope(&home.0, &digest).unwrap();
            let listener = TcpListener::bind("127.0.0.1:0").unwrap();
            let token = [71u8; crate::AUTH_TOKEN_BYTES];
            let payload = br#"{"operation":"evaluate","request":{}}"#;
            let mut owner = owner_exits.then(TestOwner::spawn);
            let owner_id = owner
                .as_ref()
                .map_or_else(std::process::id, |owner| owner.0.id());
            crate::resident_state::publish_state(
                &scope,
                1,
                owner_id,
                &digest,
                "loopback",
                listener.local_addr().unwrap().to_string(),
                &token,
            )
            .unwrap();
            let peer = thread::spawn(move || {
                let mut stream = accept_bounded(&listener);
                let mut nonce = [0; crate::AUTH_NONCE_BYTES];
                stream.read_exact(&mut nonce).unwrap();
                let received_request = match phase {
                    FailurePhase::Authentication => false,
                    FailurePhase::CommittedResponse => {
                        stream
                            .write_all(&crate::hmac_sha256(
                                &token,
                                crate::SERVER_PROOF_LABEL,
                                &nonce,
                            ))
                            .unwrap();
                        let mut proof = [0; crate::AUTH_PROOF_BYTES];
                        stream.read_exact(&mut proof).unwrap();
                        assert_eq!(
                            proof,
                            crate::hmac_sha256(&token, crate::CLIENT_PROOF_LABEL, &nonce)
                        );
                        let mut header = [0; crate::FRAME_HEADER_BYTES];
                        stream.read_exact(&mut header).unwrap();
                        assert_eq!(&header[..4], crate::REQUEST_MAGIC);
                        let mut body = vec![0; payload.len()];
                        stream.read_exact(&mut body).unwrap();
                        assert_eq!(body, payload);
                        true
                    }
                };
                if let Some(owner) = owner.as_mut() {
                    owner.stop();
                }
                match phase {
                    FailurePhase::Authentication => {
                        stream.write_all(&[0; crate::AUTH_PROOF_BYTES]).unwrap();
                    }
                    FailurePhase::CommittedResponse => {
                        // The peer received the complete authenticated request.
                        // Closing without a response leaves its commit ambiguous.
                        stream.shutdown(Shutdown::Both).unwrap();
                    }
                }
                received_request
            });
            let result = containment::try_live_or_restart(
                &home.0,
                payload,
                Instant::now() + Duration::from_secs(2),
                &digest,
            );
            let received_request = peer.join().unwrap();
            assert_eq!(
                received_request,
                matches!(phase, FailurePhase::CommittedResponse)
            );
            assert_eq!(
                result,
                Err("native_resident_live_request_failed".to_owned()),
                "fatal exchange was made restartable: {phase:?}, owner_exits={owner_exits}"
            );
        }
    }
}

#[test]
fn managed_restart_still_allows_connection_unavailable_before_exchange() {
    let home = TestHome::new();
    let digest = runtime_digest().unwrap();
    let scope = state_scope(&home.0, &digest).unwrap();
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let endpoint = listener.local_addr().unwrap().to_string();
    drop(listener);
    crate::resident_state::publish_state(
        &scope,
        1,
        std::process::id(),
        &digest,
        "loopback",
        endpoint,
        &[72u8; crate::AUTH_TOKEN_BYTES],
    )
    .unwrap();
    assert_eq!(
        containment::try_live_or_restart(
            &home.0,
            b"{}",
            Instant::now() + Duration::from_secs(1),
            &digest,
        ),
        Ok(None)
    );
}

use guard_contracts::{
    GuardHookEnvelopeV2, GuardHookPayloadKindV2, HookReviewResponseV1, NativeHookDecisionReceiptV1,
    PreToolResultV1, NATIVE_HOOK_DECISION_RECEIPT_MAX_BYTES,
};
use guard_policy_snapshot::PolicySnapshotV3;
use serde_json::Value;
use sha2::{Digest, Sha256};

fn optional_snapshot_string(
    snapshot: Option<&PolicySnapshotV3>,
    envelope: &GuardHookEnvelopeV2,
    key: &str,
) -> Option<String> {
    snapshot
        .and_then(|value| match key {
            "policy_digest" => Some(value.policy_digest.clone()),
            "rule_digest" => Some(value.rule_digest.clone()),
            "runtime_identity" => Some(value.runtime_identity.clone()),
            _ => None,
        })
        .or_else(|| {
            envelope
                .policy_snapshot
                .get(key)
                .and_then(Value::as_str)
                .map(ToOwned::to_owned)
        })
}

struct DecisionReceiptInputs<'a> {
    request_id: &'a str,
    request_digest: &'a str,
    harness: &'a str,
    event_name: &'a str,
    payload_kind: &'a GuardHookPayloadKindV2,
    decision: &'a str,
    model_output_action: &'a str,
    policy_action: Option<&'a str>,
    observed_policy_action: Option<&'a str>,
    reason_code: &'a str,
    reviewed_output_sha256: Option<&'a str>,
    observe_mode: bool,
    command_extensions: Option<&'a guard_contracts::NativeCommandReceiptBindingV1>,
    review_scope: Option<guard_contracts::NativeReviewScopeV1>,
}

fn build_decision_receipt(
    envelope: &GuardHookEnvelopeV2,
    policy_snapshot: Option<&PolicySnapshotV3>,
    inputs: DecisionReceiptInputs<'_>,
) -> Result<NativeHookDecisionReceiptV1, String> {
    let policy_generation = policy_snapshot
        .map(|value| value.generation)
        .unwrap_or(envelope.policy_generation);
    let policy_digest = optional_snapshot_string(policy_snapshot, envelope, "policy_digest");
    let rule_digest = optional_snapshot_string(policy_snapshot, envelope, "rule_digest");
    let runtime_identity = optional_snapshot_string(policy_snapshot, envelope, "runtime_identity");
    let workspace_bound = envelope.source.cwd.is_some();
    let mut identity = serde_json::json!({
        "schema": "guard-native-hook-decision-identity.v1",
        "version": 1,
        "request_id": inputs.request_id,
        "request_digest": inputs.request_digest,
        "harness": inputs.harness,
        "event_name": inputs.event_name,
        "payload_kind": inputs.payload_kind,
        "policy_generation": policy_generation,
        "policy_digest": policy_digest,
        "rule_digest": rule_digest,
        "runtime_identity": runtime_identity,
        "decision": inputs.decision,
        "model_output_action": inputs.model_output_action,
        "policy_action": inputs.policy_action,
        "observed_policy_action": inputs.observed_policy_action,
        "reason_code": inputs.reason_code,
        "workspace_bound": workspace_bound,
        "source_ref_external_allowed": envelope.source.source_ref_external_allowed,
        "reviewed_output_sha256": inputs.reviewed_output_sha256,
        "observe_mode": inputs.observe_mode,
        "deadline_budget_ms": envelope.deadline_budget_ms,
    });
    if let Some(binding) = inputs.command_extensions {
        identity["command_extensions"] = serde_json::to_value(binding)
            .map_err(|_| "native_hook_decision_receipt_digest_failed".to_owned())?;
    }
    if let Some(scope) = inputs.review_scope {
        identity["review_scope"] = serde_json::to_value(scope)
            .map_err(|_| "native_hook_decision_receipt_digest_failed".to_owned())?;
    }
    let canonical = guard_policy_snapshot::canonical_json_bytes(&identity)
        .map_err(|_| "native_hook_decision_receipt_digest_failed".to_owned())?;
    let decision_id = hex::encode(Sha256::digest(&canonical));
    let receipt = NativeHookDecisionReceiptV1 {
        schema: guard_contracts::NATIVE_HOOK_DECISION_RECEIPT_V1_SCHEMA.to_owned(),
        version: 1,
        authority: "rust".to_owned(),
        decision_id,
        request_id: inputs.request_id.to_owned(),
        request_digest: inputs.request_digest.to_owned(),
        harness: inputs.harness.to_owned(),
        event_name: inputs.event_name.to_owned(),
        payload_kind: inputs.payload_kind.clone(),
        policy_generation,
        policy_digest,
        rule_digest,
        runtime_identity,
        decision: inputs.decision.to_owned(),
        model_output_action: inputs.model_output_action.to_owned(),
        policy_action: inputs.policy_action.map(ToOwned::to_owned),
        observed_policy_action: inputs.observed_policy_action.map(ToOwned::to_owned),
        reason_code: inputs.reason_code.to_owned(),
        workspace_bound,
        source_ref_external_allowed: envelope.source.source_ref_external_allowed,
        reviewed_output_sha256: inputs.reviewed_output_sha256.map(ToOwned::to_owned),
        observe_mode: inputs.observe_mode,
        deadline_budget_ms: envelope.deadline_budget_ms,
        command_extensions: inputs.command_extensions.cloned(),
        review_scope: inputs.review_scope,
    };
    let encoded = serde_json::to_vec(&receipt)
        .map_err(|_| "native_hook_decision_receipt_encode_failed".to_owned())?;
    if encoded.len() > NATIVE_HOOK_DECISION_RECEIPT_MAX_BYTES {
        return Err("native_hook_decision_receipt_too_large".to_owned());
    }
    Ok(receipt)
}

pub(crate) fn receipt_from_pre_tool(
    envelope: &GuardHookEnvelopeV2,
    snapshot: Option<&PolicySnapshotV3>,
    request_id: &str,
    request_digest: &str,
    harness: &str,
    payload_kind: &GuardHookPayloadKindV2,
    review: (&PreToolResultV1, bool),
) -> Result<NativeHookDecisionReceiptV1, String> {
    let (result, command_absent) = review;
    build_decision_receipt(
        envelope,
        snapshot,
        DecisionReceiptInputs {
            request_id,
            request_digest,
            harness,
            event_name: "PreToolUse",
            payload_kind,
            decision: &result.decision,
            model_output_action: "not_applicable",
            policy_action: Some(&result.policy_action),
            observed_policy_action: None,
            reason_code: &result.reason_code,
            reviewed_output_sha256: None,
            observe_mode: false,
            command_extensions: result
                .command_extensions
                .as_ref()
                .map(|value| &value.binding),
            review_scope: (snapshot.is_some()
                && command_absent
                && result.command_extensions.is_none()
                && matches!(
                    result.policy_action.as_str(),
                    "review" | "require-reapproval"
                ))
            .then_some(guard_contracts::NativeReviewScopeV1::Noncommand),
        },
    )
}

pub(crate) fn receipt_from_post_tool(
    envelope: &GuardHookEnvelopeV2,
    snapshot: Option<&PolicySnapshotV3>,
    request_id: &str,
    request_digest: &str,
    harness: &str,
    payload_kind: &GuardHookPayloadKindV2,
    result: &HookReviewResponseV1,
) -> Result<NativeHookDecisionReceiptV1, String> {
    build_decision_receipt(
        envelope,
        snapshot,
        DecisionReceiptInputs {
            request_id,
            request_digest,
            harness,
            event_name: "PostToolUse",
            payload_kind,
            decision: &result.decision,
            model_output_action: &result.model_output_action,
            policy_action: result.policy_action.as_deref(),
            observed_policy_action: result.observed_policy_action.as_deref(),
            reason_code: &result.reason_code,
            reviewed_output_sha256: result.reviewed_output_sha256.as_deref(),
            observe_mode: result.observe_mode,
            command_extensions: None,
            review_scope: None,
        },
    )
}

//! Linux-only admission for a private diagnostic receiver.
//!
//! These are before/after pathname metadata checks, not an atomic proof of a
//! datagram peer inode. The receiver must bind delivered messages to its owned
//! process cohort using kernel credentials and executable/start identities.

use std::fs;
use std::io::Read;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::os::unix::net::UnixDatagram;
use std::path::{Component, Path, PathBuf};

const SOCKET_ENV: &str = "HOL_GUARD_NATIVE_PHASE_SOCKET";
const DEVICE_ENV: &str = "HOL_GUARD_NATIVE_PHASE_DEVICE";
const INODE_ENV: &str = "HOL_GUARD_NATIVE_PHASE_INODE";

#[derive(Clone, Copy, PartialEq, Eq)]
struct Identity {
    device: u64,
    inode: u64,
    uid: u32,
    mode: u32,
}

impl Identity {
    fn from_metadata(metadata: &fs::Metadata) -> Self {
        Self {
            device: metadata.dev(),
            inode: metadata.ino(),
            uid: metadata.uid(),
            mode: metadata.permissions().mode() & 0o7777,
        }
    }
}

fn identity(path: &Path, directory: bool) -> Option<Identity> {
    let metadata = fs::symlink_metadata(path).ok()?;
    let current = Identity::from_metadata(&metadata);
    let expected_mode = if directory { 0o700 } else { 0o600 };
    if current.uid != nix::unistd::geteuid().as_raw() || current.mode != expected_mode {
        return None;
    }
    if (directory && !metadata.is_dir()) || (!directory && !metadata.file_type().is_socket()) {
        return None;
    }
    Some(current)
}

fn decimal_env(name: &str) -> Option<u64> {
    let value = std::env::var(name).ok()?;
    if value.is_empty() || value.len() > 20 || !value.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    value.parse().ok()
}

fn acquire(path: &Path, device: u64, inode: u64) -> Option<UnixDatagram> {
    if !path.is_absolute()
        || path.as_os_str().as_encoded_bytes().len() >= 108
        || !path
            .components()
            .all(|part| matches!(part, Component::RootDir | Component::Normal(_)))
        || path.file_name()? != "phase.sock"
    {
        return None;
    }
    let parent = path.parent()?;
    if parent.parent()? != Path::new("/tmp")
        || !parent
            .file_name()?
            .to_str()?
            .starts_with("guard-native-phase-")
        || fs::canonicalize(parent).ok()? != parent
    {
        return None;
    }
    let parent_before = identity(parent, true)?;
    let endpoint_before = identity(path, false)?;
    if endpoint_before.device != device || endpoint_before.inode != inode {
        return None;
    }
    // This socket is diagnostic overhead. It is outside every measured request
    // socket call and is never substituted for an existing resident transport.
    let socket = UnixDatagram::unbound().ok()?;
    socket.set_nonblocking(true).ok()?;
    socket.connect(path).ok()?;
    if identity(parent, true)? != parent_before
        || identity(path, false)? != endpoint_before
        || socket.peer_addr().ok()?.as_pathname()? != path
    {
        return None;
    }
    Some(socket)
}

fn parse_start_ticks(bytes: &[u8], expected_pid: u32) -> Option<u64> {
    let text = std::str::from_utf8(bytes).ok()?;
    let (head, fields) = text.rsplit_once(") ")?;
    let pid = head.split_once(" (")?.0.parse::<u32>().ok()?;
    if pid != expected_pid {
        return None;
    }
    let value = fields.split_whitespace().nth(19)?;
    if value.is_empty() || value.len() > 20 || !value.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    let start = value.parse().ok()?;
    (start != 0).then_some(start)
}

pub(super) fn self_start_ticks() -> Option<u64> {
    let mut bytes = Vec::with_capacity(4097);
    fs::File::open("/proc/self/stat")
        .ok()?
        .take(4097)
        .read_to_end(&mut bytes)
        .ok()?;
    if bytes.len() > 4096 {
        return None;
    }
    parse_start_ticks(&bytes, std::process::id())
}

pub(super) fn from_environment() -> Option<UnixDatagram> {
    let path = PathBuf::from(std::env::var_os(SOCKET_ENV)?);
    acquire(&path, decimal_env(DEVICE_ENV)?, decimal_env(INODE_ENV)?)
}

#[cfg(test)]
mod tests {
    use super::*;
    include!("native_phase_endpoint_tests.rs");
}

use std::os::unix::fs::{symlink, DirBuilderExt};
use std::sync::atomic::{AtomicU64, Ordering};

static NEXT_DIRECTORY: AtomicU64 = AtomicU64::new(0);

struct Fixture {
    directory: PathBuf,
    directory_identity: Identity,
    path: PathBuf,
    socket_identity: Identity,
    _receiver: UnixDatagram,
}

impl Fixture {
    fn new() -> Self {
        let mut owned = None;
        for _ in 0..16 {
            let next = NEXT_DIRECTORY.fetch_add(1, Ordering::Relaxed);
            let path = PathBuf::from(format!(
                "/tmp/guard-native-phase-{}-{next}", std::process::id()
            ));
            match fs::DirBuilder::new().mode(0o700).create(&path) {
                Ok(()) => {
                    owned = Some(path);
                    break;
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
                Err(error) => panic!("cannot create owned diagnostic fixture: {error}"),
            }
        }
        let directory = owned.expect("bounded diagnostic fixture names exhausted");
        let path = directory.join("phase.sock");
        let receiver = UnixDatagram::bind(&path).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600)).unwrap();
        Self {
            directory_identity: identity(&directory, true).unwrap(),
            socket_identity: identity(&path, false).unwrap(),
            directory,
            path,
            _receiver: receiver,
        }
    }

    fn acquire(&self) -> Option<UnixDatagram> {
        acquire(&self.path, self.socket_identity.device, self.socket_identity.inode)
    }
}

fn same_object(left: Identity, right: Identity) -> bool {
    (left.device, left.inode, left.uid) == (right.device, right.inode, right.uid)
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let Ok(parent) = fs::symlink_metadata(&self.directory) else { return };
        if !parent.is_dir() || !same_object(Identity::from_metadata(&parent), self.directory_identity) {
            return;
        }
        if let Ok(socket) = fs::symlink_metadata(&self.path) {
            if socket.file_type().is_socket()
                && same_object(Identity::from_metadata(&socket), self.socket_identity)
            {
                let _ = fs::remove_file(&self.path);
            }
        }
        // Only the exact newly created, now-empty directory is removed.
        let _ = fs::remove_dir(&self.directory);
    }
}

#[test]
fn private_endpoint_requires_exact_owned_socket_identity() {
    let fixture = Fixture::new();
    let socket = fixture.acquire().unwrap();
    assert_eq!(socket.peer_addr().unwrap().as_pathname(), Some(fixture.path.as_path()));
    assert!(acquire(&fixture.path, fixture.socket_identity.device, fixture.socket_identity.inode + 1).is_none());
    assert!(acquire(&fixture.path, fixture.socket_identity.device.wrapping_add(1), fixture.socket_identity.inode).is_none());
}

#[test]
fn directory_and_socket_modes_are_admission_boundaries() {
    let fixture = Fixture::new();
    fs::set_permissions(&fixture.directory, fs::Permissions::from_mode(0o755)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::set_permissions(&fixture.directory, fs::Permissions::from_mode(0o700)).unwrap();
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o666)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o600)).unwrap();
    assert!(fixture.acquire().is_some());
}

#[test]
fn symlink_endpoint_and_unadmitted_path_shapes_are_refused() {
    let fixture = Fixture::new();
    let second = Fixture::new();
    fs::remove_file(&second.path).unwrap();
    symlink(&fixture.path, &second.path).unwrap();
    assert!(acquire(&second.path, fixture.socket_identity.device, fixture.socket_identity.inode).is_none());
    fs::remove_file(&second.path).unwrap();
    assert!(acquire(Path::new("phase.sock"), 0, 0).is_none());
    assert!(acquire(&fixture.directory.join("../phase.sock"), 0, 0).is_none());
    assert!(acquire(&fixture.directory.join("other.sock"), 0, 0).is_none());
    assert!(acquire(Path::new("/tmp/phase.sock"), 0, 0).is_none());
}

#[test]
fn regular_file_cannot_stand_in_for_the_diagnostic_socket() {
    let fixture = Fixture::new();
    fs::remove_file(&fixture.path).unwrap();
    fs::write(&fixture.path, b"controlled nonsocket").unwrap();
    fs::set_permissions(&fixture.path, fs::Permissions::from_mode(0o600)).unwrap();
    assert!(fixture.acquire().is_none());
    fs::remove_file(&fixture.path).unwrap();
}

#[test]
fn startup_identity_parser_handles_comm_delimiters_and_refuses_ambiguity() {
    let stat = format!("{} (controlled ) name) S {} 777\n",
        std::process::id(), "0 ".repeat(18));
    assert_eq!(parse_start_ticks(stat.as_bytes(), std::process::id()), Some(777));
    assert!(parse_start_ticks(stat.as_bytes(), std::process::id().wrapping_add(1)).is_none());
    assert!(parse_start_ticks(b"123 (short) S 0", 123).is_none());
    let zero = stat.replace("777", "0");
    assert!(parse_start_ticks(zero.as_bytes(), std::process::id()).is_none());
    assert!(self_start_ticks().is_some());
}

#[test]
fn observation_macro_returns_original_values_and_evaluates_once() {
    let calls = std::cell::Cell::new(0);
    let value = Box::new([3u8; 8]);
    let identity = (&*value) as *const [u8; 8];
    let result: Result<Box<[u8; 8]>, ()> = crate::observe_native_phase!(ClientConnect, {
        calls.set(calls.get() + 1);
        Ok(value)
    });
    assert_eq!(calls.get(), 1);
    assert_eq!((&*result.unwrap()) as *const [u8; 8], identity);
    let error = Box::new([9u8; 8]);
    let error_identity = (&*error) as *const [u8; 8];
    let result: Result<(), Box<[u8; 8]>> = crate::observe_native_phase!(ClientConnect, {
        calls.set(calls.get() + 1);
        Err(error)
    });
    assert_eq!(calls.get(), 2);
    assert_eq!((&*result.unwrap_err()) as *const [u8; 8], error_identity);
}

