    };
    *collector.aggregates.lock().unwrap() = [maximum; PHASE_COUNT];
    collector.active.store(usize::MAX, Ordering::Relaxed);
    let bytes = serde_json::to_vec(&snapshot_collector(&collector).unwrap()).unwrap();
