//! Keep each client phase inside its original monotonic deadline.
use std::cell::Cell;
use std::io::{self, Read, Write};
use std::time::{Duration, Instant};

use crate::ResidentStream;

pub(super) struct DeadlineStream<'a> {
    stream: &'a mut dyn ResidentStream,
    deadline: Instant,
    read_deadline: Cell<Instant>,
    write_deadline: Cell<Instant>,
}

fn remaining(deadline: Instant) -> io::Result<Duration> {
    deadline
        .checked_duration_since(Instant::now())
        .filter(|remaining| !remaining.is_zero())
        .ok_or_else(|| io::Error::from(io::ErrorKind::TimedOut))
}

impl<'a> DeadlineStream<'a> {
    pub(super) fn new(stream: &'a mut dyn ResidentStream, deadline: Instant) -> Self {
        Self {
            stream,
            deadline,
            read_deadline: Cell::new(deadline),
            write_deadline: Cell::new(deadline),
        }
    }

    fn phase_deadline(&self, timeout: Option<Duration>) -> io::Result<Instant> {
        if timeout.is_some_and(|timeout| timeout.is_zero()) {
            return Err(io::Error::from(io::ErrorKind::InvalidInput));
        }
        // Callers can narrow the current phase (authentication), but no
        // timeout reset or None can extend the original request deadline.
        Ok(timeout
            .and_then(|timeout| Instant::now().checked_add(timeout))
            .map_or(self.deadline, |deadline| deadline.min(self.deadline)))
    }
}

impl Read for DeadlineStream<'_> {
    fn read(&mut self, output: &mut [u8]) -> io::Result<usize> {
        let deadline = self.read_deadline.get();
        let result = match self
            .stream
            .set_resident_read_timeout(Some(remaining(deadline)?))
        {
            Ok(()) => self.stream.read(output),
            Err(error) => match self
                .stream
                .read_buffered_after_timeout_error(output, &error, deadline)
            {
                Some(result) => result,
                None => return Err(error),
            },
        };
        // Socket timeout granularity can allow a successful final read past
        // the deadline. Such a response must not be accepted as timely.
        remaining(deadline)?;
        result
    }
}

impl Write for DeadlineStream<'_> {
    fn write(&mut self, input: &[u8]) -> io::Result<usize> {
        let deadline = self.write_deadline.get();
        self.stream
            .set_resident_write_timeout(Some(remaining(deadline)?))?;
        let result = self.stream.write(input);
        remaining(deadline)?;
        result
    }

    fn flush(&mut self) -> io::Result<()> {
        let deadline = self.write_deadline.get();
        let result = match self
            .stream
            .set_resident_write_timeout(Some(remaining(deadline)?))
        {
            Ok(()) => self.stream.flush(),
            Err(error) => match self.stream.flush_after_timeout_error(&error, deadline) {
                Some(result) => result,
                None => return Err(error),
            },
        };
        remaining(deadline)?;
        result
    }
}

impl ResidentStream for DeadlineStream<'_> {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        let deadline = self.phase_deadline(timeout)?;
        self.stream
            .set_resident_read_timeout(Some(remaining(deadline)?))?;
        self.read_deadline.set(deadline);
        Ok(())
    }

    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        let deadline = self.phase_deadline(timeout)?;
        self.stream
            .set_resident_write_timeout(Some(remaining(deadline)?))?;
        self.write_deadline.set(deadline);
        Ok(())
    }

    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.stream.set_resident_nonblocking(nonblocking)
    }

    fn configure_low_latency(&self) -> io::Result<()> {
        self.stream.configure_low_latency()
    }
}

use super::*;
use std::io::{Read, Write};
use std::net::{Shutdown, TcpListener};
use std::thread;

const TOKEN: [u8; crate::AUTH_TOKEN_BYTES] = [0x5a; crate::AUTH_TOKEN_BYTES];

fn socket_pair() -> (TcpStream, TcpStream) {
    let listener = TcpListener::bind((Ipv4Addr::LOCALHOST, 0)).unwrap();
    let client = TcpStream::connect(listener.local_addr().unwrap()).unwrap();
    let (server, _) = listener.accept().unwrap();
    for stream in [&client, &server] {
        stream.set_nodelay(true).unwrap();
        stream
            .set_read_timeout(Some(Duration::from_secs(2)))
            .unwrap();
        stream
            .set_write_timeout(Some(Duration::from_secs(2)))
            .unwrap();
    }
    (client, server)
}

fn accept_authentication(stream: &mut TcpStream, slow_proof: bool) -> io::Result<()> {
    let mut nonce = [0u8; AUTH_NONCE_BYTES];
    stream.read_exact(&mut nonce)?;
    let proof = hmac_sha256(&TOKEN, SERVER_PROOF_LABEL, &nonce);
    if slow_proof {
        // Every fragment arrives within the old socket inactivity timeout;
        // their aggregate duration exceeds the authentication phase budget.
        for chunk in proof.chunks(4) {
            thread::sleep(Duration::from_millis(40));
            stream.write_all(chunk)?;
        }
    } else {
        stream.write_all(&proof)?;
    }
    let mut client_proof = [0u8; AUTH_PROOF_BYTES];
    stream.read_exact(&mut client_proof)?;
    assert_eq!(
        client_proof,
        hmac_sha256(&TOKEN, CLIENT_PROOF_LABEL, &nonce)
    );
    Ok(())
}

fn accept_request(stream: &mut TcpStream) -> io::Result<[u8; FRAME_REQUEST_ID_BYTES]> {
    let mut header = [0u8; FRAME_HEADER_BYTES];
    stream.read_exact(&mut header)?;
    assert_eq!(&header[..4], REQUEST_MAGIC);
    let request_id = header[4..4 + FRAME_REQUEST_ID_BYTES].try_into().unwrap();
    let length = u32::from_be_bytes(header[FRAME_HEADER_BYTES - 4..].try_into().unwrap()) as usize;
    let mut payload = vec![0u8; length];
    stream.read_exact(&mut payload)?;
    assert_eq!(payload, b"{}");
    assert_eq!(
        &header[4 + FRAME_REQUEST_ID_BYTES..FRAME_HEADER_BYTES - 4],
        Sha256::digest(&payload).as_slice(),
    );
    Ok(request_id)
}

fn response_header(request_id: &[u8; FRAME_REQUEST_ID_BYTES], response: &[u8]) -> Vec<u8> {
    let mut header = Vec::new();
    header.extend_from_slice(RESPONSE_MAGIC);
    header.extend_from_slice(request_id);
    header.extend_from_slice(&Sha256::digest(response));
    header.extend_from_slice(&(response.len() as u32).to_be_bytes());
    header
}

#[test]
fn timely_authenticated_socket_response_is_unchanged() {
    let (mut client, mut server) = socket_pair();
    let peer = thread::spawn(move || -> io::Result<()> {
        accept_authentication(&mut server, false)?;
        let request_id = accept_request(&mut server)?;
        server.write_all(&response_header(&request_id, b"{}"))?;
        server.write_all(b"{}")
    });
    let result = exchange_request(
        &mut client,
        &TOKEN,
        b"{}",
        Instant::now() + Duration::from_secs(2),
    )
    .unwrap();
    assert_eq!(result, b"{}");
    peer.join().unwrap().unwrap();
}

