    int result = owner->base.xOpen(&owner->base, expected_name, &file->base,
        SQLITE_OPEN_MAIN_DB | SQLITE_OPEN_READWRITE, &out);
    CHECK(result == expected_result && out == SQLITE_OPEN_READONLY && errno == EIO);
