static void *other_thread(void *pointer) {
    sqlite3_file *file = pointer;
    CHECK(file->pMethods->xSync(file, SQLITE_SYNC_FULL | SQLITE_SYNC_DATAONLY) == SQLITE_IOERR_FSYNC);
