int main(int argc, char **argv) {
    CHECK(argc == 2);
    expected_name = "/owned.db";
    if (strcmp(argv[1], "v1") == 0 || strcmp(argv[1], "v2") == 0 || strcmp(argv[1], "v3") == 0) {
        version = argv[1][1] - '0';
        test_forward();
    } else if (strcmp(argv[1], "optional") == 0) {
        optional_methods = 0;
        test_forward();
    } else if (strcmp(argv[1], "vfs") == 0) {
        test_vfs();
    } else {
        GuardVfs owner;
        if (strcmp(argv[1], "failed_open_without_methods") == 0) {
            open_result = SQLITE_CANTOPEN;
            open_has_methods = 0;
        } else if (strcmp(argv[1], "failed_open_with_methods") == 0) open_result = SQLITE_IOERR;
        else if (strcmp(argv[1], "unknown_version") == 0) version = 4;
        init(&owner);
        int expected = version == 4 ? SQLITE_CANTOPEN : open_result;
        GuardFile *file = opened(&owner, expected);
        if (strcmp(argv[1], "failed_open_without_methods") == 0) {
            CHECK(!file->base.pMethods && owner.active == 0 && owner.unsupported == 0 && closes == 0);
        } else if (strcmp(argv[1], "unknown_version") == 0) {
            CHECK(!file->base.pMethods && owner.active == 0 && owner.unsupported == 1 && closes == 1);
        } else {
            if (strcmp(argv[1], "thread") == 0) {
                pthread_t thread;
                CHECK(pthread_create(&thread, 0, other_thread, file) == 0);
                CHECK(pthread_join(thread, 0) == 0);
                CHECK(owner.values[GUARD_WRITER][GUARD_MAIN][G_CROSS_THREAD] == 1);
            } else if (strcmp(argv[1], "saturation") == 0) {
                owner.values[GUARD_WRITER][GUARD_MAIN][G_SYNC] = INT64_MAX;
                file->base.pMethods->xSync(&file->base, SQLITE_SYNC_FULL | SQLITE_SYNC_DATAONLY);
                CHECK(owner.values[GUARD_WRITER][GUARD_MAIN][G_SYNC] == INT64_MAX && owner.saturated);
            } else CHECK(strcmp(argv[1], "failed_open_with_methods") == 0);
            CHECK(file->base.pMethods->xClose(&file->base) == SQLITE_IOERR_CLOSE && closes == 1);
            CHECK(owner.active == 0);
        }
        free(file);
    }
    printf("{\"control\":\"%s\",\"passed\":true,\"scope\":\"portable_callback_fixture\"}\n", argv[1]);
    return 0;
}

/* Opt-in SQLite VFS observation. No payload, SQL, or event retention.
 * One private owned database path is retained only for scope admission. */
#ifndef GUARD_SQLITE_VFS_H
#define GUARD_SQLITE_VFS_H

#if defined(_WIN32)
#error "This diagnostic currently requires a POSIX pthread host."
#endif
#include <errno.h>
#include <limits.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>
#include <sqlite3ext.h>
SQLITE_EXTENSION_INIT3

enum { GUARD_OTHER, GUARD_WRITER, GUARD_READBACK, GUARD_SCOPES };
enum { GUARD_AUX, GUARD_MAIN, GUARD_WAL, GUARD_JOURNAL, GUARD_ROLES };
enum {
    G_OPEN, G_OPEN_ERROR, G_CLOSE, G_CLOSE_ERROR,
    G_READ, G_READ_ERROR, G_READ_REQUESTED, G_READ_OK_BYTES,
    G_WRITE, G_WRITE_ERROR, G_WRITE_REQUESTED, G_WRITE_OK_BYTES,
    G_WRITE_ERROR_REQUESTED, G_SYNC, G_SYNC_ERROR, G_SYNC_NORMAL,
    G_SYNC_FULL, G_SYNC_DATAONLY, G_TRUNCATE, G_TRUNCATE_ERROR,
    G_FETCH, G_FETCH_MAPPED, G_CROSS_THREAD, GUARD_METRICS
};
typedef struct GuardVfs GuardVfs;
typedef struct GuardFile {
    sqlite3_file base;
    sqlite3_io_methods methods;
    GuardVfs *owner;
    pthread_t opening_thread;
    int scope;
    int role;
    /* The real sqlite3_file starts at the next aligned byte after this object. */
} GuardFile;
struct GuardVfs {
    sqlite3_vfs base;
    sqlite3_vfs *original;
    sqlite3_mutex *mutex;
    sqlite3_int64 values[GUARD_SCOPES][GUARD_ROLES][GUARD_METRICS];
    sqlite3_int64 active;
    sqlite3_int64 opening;
    sqlite3_int64 unsupported;
    sqlite3_int64 outside_owned;
    char *database;
    sqlite3_int64 saturated;
    int registered;
    int abandoned;
    int permanent;
    char name[80];
};
#define GUARD_FILE_OFFSET ((sizeof(GuardFile) + 7u) & ~(size_t)7u)

sqlite3_file *guard_real(sqlite3_file *file);
void guard_add(GuardVfs *owner, sqlite3_int64 *field, sqlite3_int64 amount);
void guard_measure(GuardFile *file, int metric, sqlite3_int64 amount);
void guard_touch(GuardFile *file);
int guard_methods(GuardFile *file);
int guard_open(sqlite3_vfs *, const char *, sqlite3_file *, int, int *);
void guard_vfs_methods(GuardVfs *);
void guard_control(sqlite3_context *, int, sqlite3_value **);
void guard_destroy(void *);

#endif

/* Each wrapper forwards the original buffer, flags, offset, and return code. */
#include "guard_vfs.h"

sqlite3_file *guard_real(sqlite3_file *file) {
    return (sqlite3_file *)((unsigned char *)file + GUARD_FILE_OFFSET);
}

void guard_add(GuardVfs *owner, sqlite3_int64 *field, sqlite3_int64 amount) {
    if (amount < 0 || *field > INT64_MAX - amount) {
        *field = INT64_MAX;
        owner->saturated = 1;
    } else {
        *field += amount;
    }
}

void guard_measure(GuardFile *file, int metric, sqlite3_int64 amount) {
    int saved = errno;
    GuardVfs *owner = file->owner;
    sqlite3_mutex_enter(owner->mutex);
    guard_add(owner, &owner->values[file->scope][file->role][metric], amount);
    sqlite3_mutex_leave(owner->mutex);
    errno = saved;
}

void guard_touch(GuardFile *file) {
    int saved = errno;
    if (!pthread_equal(file->opening_thread, pthread_self())) {
        guard_measure(file, G_CROSS_THREAD, 1);
    }
    errno = saved;
}

static int io_close(sqlite3_file *base) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xClose(real);
    int saved = errno;
    guard_measure(file, G_CLOSE, 1);
    if (result != SQLITE_OK) guard_measure(file, G_CLOSE_ERROR, 1);
    sqlite3_mutex_enter(file->owner->mutex);
    file->owner->active--;
    sqlite3_mutex_leave(file->owner->mutex);
    base->pMethods = 0;
    errno = saved;
    return result;
}

static int io_read(sqlite3_file *base, void *buffer, int amount, sqlite3_int64 offset) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xRead(real, buffer, amount, offset);
    int saved = errno;
    guard_measure(file, G_READ, 1);
    guard_measure(file, G_READ_REQUESTED, amount);
    guard_measure(file, result == SQLITE_OK ? G_READ_OK_BYTES : G_READ_ERROR,
                  result == SQLITE_OK ? amount : 1);
    errno = saved;
    return result;
}

static int io_write(sqlite3_file *base, const void *buffer, int amount, sqlite3_int64 offset) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xWrite(real, buffer, amount, offset);
    int saved = errno;
    guard_measure(file, G_WRITE, 1);
    guard_measure(file, G_WRITE_REQUESTED, amount);
    if (result == SQLITE_OK) {
        guard_measure(file, G_WRITE_OK_BYTES, amount);
    } else {
        /* A failing xWrite may have written a prefix. Its actual byte count is unknown. */
        guard_measure(file, G_WRITE_ERROR, 1);
        guard_measure(file, G_WRITE_ERROR_REQUESTED, amount);
    }
    errno = saved;
    return result;
}

static int io_sync(sqlite3_file *base, int flags) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xSync(real, flags);
    int saved = errno;
    guard_measure(file, G_SYNC, 1);
    if (result != SQLITE_OK) guard_measure(file, G_SYNC_ERROR, 1);
    if ((flags & 0x0f) == SQLITE_SYNC_NORMAL) guard_measure(file, G_SYNC_NORMAL, 1);
    if ((flags & 0x0f) == SQLITE_SYNC_FULL) guard_measure(file, G_SYNC_FULL, 1);
    if (flags & SQLITE_SYNC_DATAONLY) guard_measure(file, G_SYNC_DATAONLY, 1);
    errno = saved;
    return result;
}

static int io_truncate(sqlite3_file *base, sqlite3_int64 size) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xTruncate(real, size);
    int saved = errno;
    guard_measure(file, G_TRUNCATE, 1);
    if (result != SQLITE_OK) guard_measure(file, G_TRUNCATE_ERROR, 1);
    errno = saved;
    return result;
}

static int io_fetch(sqlite3_file *base, sqlite3_int64 offset, int amount, void **out) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    int result = real->pMethods->xFetch(real, offset, amount, out);
    int saved = errno;
    guard_measure(file, G_FETCH, 1);
    if (result == SQLITE_OK && *out) guard_measure(file, G_FETCH_MAPPED, 1);
    errno = saved;
    return result;
}

#define FORWARD_INT(name, declaration, arguments) \
    static int io_##name declaration { \
        GuardFile *file = (GuardFile *)base; \
        sqlite3_file *real = guard_real(base); \
        guard_touch(file); \
        return real->pMethods->name arguments; \
    }

FORWARD_INT(xFileSize, (sqlite3_file *base, sqlite3_int64 *size), (real, size))
FORWARD_INT(xLock, (sqlite3_file *base, int level), (real, level))
FORWARD_INT(xUnlock, (sqlite3_file *base, int level), (real, level))
FORWARD_INT(xCheckReservedLock, (sqlite3_file *base, int *out), (real, out))
FORWARD_INT(xFileControl, (sqlite3_file *base, int operation, void *out), (real, operation, out))
FORWARD_INT(xSectorSize, (sqlite3_file *base), (real))
FORWARD_INT(xDeviceCharacteristics, (sqlite3_file *base), (real))
FORWARD_INT(xShmMap, (sqlite3_file *base, int page, int size, int extend, void volatile **out),
            (real, page, size, extend, out))
FORWARD_INT(xShmLock, (sqlite3_file *base, int offset, int count, int flags), (real, offset, count, flags))
FORWARD_INT(xShmUnmap, (sqlite3_file *base, int remove), (real, remove))
FORWARD_INT(xUnfetch, (sqlite3_file *base, sqlite3_int64 offset, void *value), (real, offset, value))

static void io_barrier(sqlite3_file *base) {
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    guard_touch(file);
    real->pMethods->xShmBarrier(real);
}

int guard_methods(GuardFile *file) {
    const sqlite3_io_methods *original = guard_real(&file->base)->pMethods;
    sqlite3_io_methods *out = &file->methods;
    memset(out, 0, sizeof(*out));
    if (original->iVersion < 1 || original->iVersion > 3) return SQLITE_CANTOPEN;
    out->iVersion = original->iVersion;
#define ASSIGN(method, replacement) out->method = original->method ? replacement : 0
    ASSIGN(xClose, io_close);
    ASSIGN(xRead, io_read);
    ASSIGN(xWrite, io_write);
    ASSIGN(xTruncate, io_truncate);
    ASSIGN(xSync, io_sync);
    ASSIGN(xFileSize, io_xFileSize);
    ASSIGN(xLock, io_xLock);
    ASSIGN(xUnlock, io_xUnlock);
    ASSIGN(xCheckReservedLock, io_xCheckReservedLock);
    ASSIGN(xFileControl, io_xFileControl);
    ASSIGN(xSectorSize, io_xSectorSize);
    ASSIGN(xDeviceCharacteristics, io_xDeviceCharacteristics);
    if (original->iVersion >= 2) {
        ASSIGN(xShmMap, io_xShmMap);
        ASSIGN(xShmLock, io_xShmLock);
        ASSIGN(xShmBarrier, io_barrier);
        ASSIGN(xShmUnmap, io_xShmUnmap);
    }
    if (original->iVersion >= 3) {
        ASSIGN(xFetch, io_fetch);
        ASSIGN(xUnfetch, io_xUnfetch);
    }
#undef ASSIGN
    file->base.pMethods = out;
    return SQLITE_OK;
}

/* Named, non-default VFS. All original VFS callbacks receive their original VFS. */
#include "guard_vfs.h"

static GuardVfs *owner_of(sqlite3_vfs *vfs) {
    return (GuardVfs *)vfs->pAppData;
}

int guard_open(sqlite3_vfs *vfs, const char *name, sqlite3_file *base, int flags, int *out) {
    GuardVfs *owner = owner_of(vfs);
    GuardFile *file = (GuardFile *)base;
    sqlite3_file *real = guard_real(base);
    int incoming = errno;
    memset(file, 0, sizeof(*file));
    memset(real, 0, (size_t)owner->original->szOsFile);
    file->owner = owner;
    file->opening_thread = pthread_self();
    if (flags & SQLITE_OPEN_MAIN_DB) file->role = GUARD_MAIN;
    else if (flags & SQLITE_OPEN_WAL) file->role = GUARD_WAL;
    else if (flags & SQLITE_OPEN_MAIN_JOURNAL) file->role = GUARD_JOURNAL;
    int outside_owned = 0;
    if (name && file->role != GUARD_AUX) {
        const char *database = sqlite3_filename_database(name);
        outside_owned = !database || strcmp(database, owner->database) != 0;
        /* SQLite >= 3.31 supplies associated URI parameters for WAL/journal names. */
        const char *scope = sqlite3_uri_parameter(name, "guard_scope");
        if (scope && strcmp(scope, "writer") == 0) file->scope = GUARD_WRITER;
        else if (scope && strcmp(scope, "readback") == 0) file->scope = GUARD_READBACK;
    }
    if (outside_owned) {
        file->scope = GUARD_OTHER;
        file->role = GUARD_AUX;
    }
    sqlite3_mutex_enter(owner->mutex);
    if (!owner->registered) {
        sqlite3_mutex_leave(owner->mutex);
        errno = incoming;
        return SQLITE_CANTOPEN;
    }
    owner->opening++;
    if (outside_owned) guard_add(owner, &owner->outside_owned, 1);
    sqlite3_mutex_leave(owner->mutex);
    errno = incoming;
    int result = owner->original->xOpen(owner->original, name, real, flags, out);
    int saved = errno;
    int wrapped = 0;
    int unsupported = 0;
    if (real->pMethods) {
        wrapped = guard_methods(file) == SQLITE_OK;
        if (!wrapped) {
            unsupported = 1;
            /* Unsupported method versions are a refused diagnostic host, not coverage. */
            if (real->pMethods->xClose) real->pMethods->xClose(real);
            real->pMethods = 0;
            if (result == SQLITE_OK) result = SQLITE_CANTOPEN;
        }
    }
    if (result == SQLITE_OK && !wrapped) {
        unsupported = 1;
        result = SQLITE_CANTOPEN;
    }
    guard_measure(file, G_OPEN, 1);
    if (result != SQLITE_OK) guard_measure(file, G_OPEN_ERROR, 1);
    sqlite3_mutex_enter(owner->mutex);
    owner->opening--;
    if (wrapped) owner->active++;
    if (unsupported) owner->unsupported++;
    sqlite3_mutex_leave(owner->mutex);
    errno = saved;
    return result;
}

#define VFS_INT(method, declaration, arguments) \
    static int vfs_##method declaration { \
        sqlite3_vfs *original = owner_of(vfs)->original; \
        return original->method arguments; \
    }
VFS_INT(xDelete, (sqlite3_vfs *vfs, const char *name, int sync_dir), (original, name, sync_dir))
VFS_INT(xAccess, (sqlite3_vfs *vfs, const char *name, int flags, int *out), (original, name, flags, out))
VFS_INT(xFullPathname, (sqlite3_vfs *vfs, const char *name, int size, char *out),
        (original, name, size, out))
VFS_INT(xRandomness, (sqlite3_vfs *vfs, int size, char *out), (original, size, out))
VFS_INT(xSleep, (sqlite3_vfs *vfs, int microseconds), (original, microseconds))
VFS_INT(xCurrentTime, (sqlite3_vfs *vfs, double *out), (original, out))
VFS_INT(xGetLastError, (sqlite3_vfs *vfs, int size, char *out), (original, size, out))
VFS_INT(xCurrentTimeInt64, (sqlite3_vfs *vfs, sqlite3_int64 *out), (original, out))
VFS_INT(xSetSystemCall, (sqlite3_vfs *vfs, const char *name, sqlite3_syscall_ptr call),
        (original, name, call))

static void *vfs_dlopen(sqlite3_vfs *vfs, const char *name) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    return original->xDlOpen(original, name);
}
static void vfs_dlerror(sqlite3_vfs *vfs, int size, char *out) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    original->xDlError(original, size, out);
}
static void (*vfs_dlsym(sqlite3_vfs *vfs, void *handle, const char *name))(void) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    return original->xDlSym(original, handle, name);
}
static void vfs_dlclose(sqlite3_vfs *vfs, void *handle) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    original->xDlClose(original, handle);
}
static sqlite3_syscall_ptr vfs_getsystemcall(sqlite3_vfs *vfs, const char *name) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    return original->xGetSystemCall(original, name);
}
static const char *vfs_nextsystemcall(sqlite3_vfs *vfs, const char *name) {
    sqlite3_vfs *original = owner_of(vfs)->original;
    return original->xNextSystemCall(original, name);
}

void guard_vfs_methods(GuardVfs *owner) {
    sqlite3_vfs *out = &owner->base;
    sqlite3_vfs *original = owner->original;
    out->iVersion = original->iVersion;
    out->szOsFile = (int)GUARD_FILE_OFFSET + original->szOsFile;
    out->mxPathname = original->mxPathname;
    out->zName = owner->name;
    out->pAppData = owner;
    out->xOpen = guard_open;
#define ASSIGN(method, replacement) out->method = original->method ? replacement : 0
    ASSIGN(xDelete, vfs_xDelete);
    ASSIGN(xAccess, vfs_xAccess);
    ASSIGN(xFullPathname, vfs_xFullPathname);
    ASSIGN(xDlOpen, vfs_dlopen);
    ASSIGN(xDlError, vfs_dlerror);
    ASSIGN(xDlSym, vfs_dlsym);
    ASSIGN(xDlClose, vfs_dlclose);
    ASSIGN(xRandomness, vfs_xRandomness);
    ASSIGN(xSleep, vfs_xSleep);
    ASSIGN(xCurrentTime, vfs_xCurrentTime);
    ASSIGN(xGetLastError, vfs_xGetLastError);
    if (original->iVersion >= 2) ASSIGN(xCurrentTimeInt64, vfs_xCurrentTimeInt64);
    if (original->iVersion >= 3) {
        ASSIGN(xSetSystemCall, vfs_xSetSystemCall);
        ASSIGN(xGetSystemCall, vfs_getsystemcall);
        ASSIGN(xNextSystemCall, vfs_nextsystemcall);
    }
#undef ASSIGN
}

#!/usr/bin/env python3
"""Prove native ownership of decision-critical hook I/O.

Python transports hooks; Rust owns source bytes, path classification, file identity and content equivalence.
This gate inventories Python I/O and hashes, follows hook calls, and rejects new native-branch operations.
Off/shadow compatibility and differential work remain visible.
"""

from __future__ import annotations

import argparse
import ast
import json
import sys
from collections import Counter
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from pathlib import Path
from typing import Final, cast

if __package__ is None:
    sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from scripts.ci.rust_io_ownership_contract import capability_contract, scoped_io_category
from scripts.ci.rust_io_ownership_resolver import FunctionRecordLike, resolve_call, scoped_nodes
from scripts.ci.rust_io_ownership_scopes import (
    _ASYNC_POLICY_PATHS,
    _COMPATIBILITY_PATHS,
    _PERSISTENCE_PATH_PREFIXES,
    _TRANSPORT_DECODE_PATHS,
    _TRANSPORT_IDENTITY_PATHS,
)

SCHEMA: Final = "hol-guard.decision-critical-io.v1"
NATIVE_MODES: Final = frozenset({"auto", "force"})
COMPATIBILITY_MODES: Final = frozenset({"off", "shadow"})

_FS_METHODS: Final = frozenset(
    {
        "open",
        "read",
        "read_bytes",
        "read_text",
        "stat",
        "lstat",
        "readlink",
        "iterdir",
        "glob",
        "rglob",
        "resolve",
        "exists",
        "is_file",
        "is_dir",
        "is_symlink",
        "realpath",
    }
)
_FS_FUNCTIONS: Final = frozenset({"open", "readlink", "stat", "lstat", "listdir", "scandir"})
_HASH_FUNCTIONS: Final = frozenset({"md5", "sha1", "sha224", "sha256", "sha384", "sha512", "blake2b", "blake2s"})
_ARCHIVE_MODULES: Final = frozenset({"tarfile", "zipfile", "gzip", "bz2", "lzma", "shutil"})
_DECODE_FUNCTIONS: Final = frozenset({"b64decode", "loads", "decode", "unpack", "decompress"})
_EQUIVALENCE_FUNCTIONS: Final = frozenset({"output_equivalent", "parity_signature", "sha256_text"})


@dataclass(frozen=True, slots=True)
class RootSpec:
    path: str
    name: str
    class_name: str | None = None


@dataclass(frozen=True, slots=True)
class FunctionRecord:
    path: str
    name: str
    qualname: str
    node: ast.FunctionDef | ast.AsyncFunctionDef


@dataclass(frozen=True, slots=True)
class IoObservation:
    path: str
    line: int
    operation: str
    kind: str
    category: str
    reachable: bool


_POSTURE_ROOT: Final = RootSpec(
    "src/codex_plugin_scanner/guard/daemon/hook_availability_policy.py",
    "hook_review_is_recording_only",
)
# These callables are injected as configuration dependencies. A static call
# graph cannot follow an arbitrary callable argument, so inventory each actual
# daemon implementation explicitly, including its held-parent callback.
_CONFIG_SCOPE_ROOTS: Final = tuple(
    RootSpec("src/codex_plugin_scanner/guard/daemon/config_read_scope.py", name, "HookConfigReadScope")
    for name in ("read_toml", "__call__", "_validate_held_parent")
)

ROOTS: Final = (
    RootSpec(
        "src/codex_plugin_scanner/guard/daemon/hook_worker.py",
        "review_http_payload",
        "HookWorker",
    ),
    RootSpec(
        "src/codex_plugin_scanner/guard/daemon/hook_worker.py",
        "_review_post_tool_http",
        "HookWorker",
    ),
    RootSpec("src/codex_plugin_scanner/guard/native_hook_edge.py", "review_raw_hook_native"),
    RootSpec("src/codex_plugin_scanner/guard/native_runtime.py", "review_post_tool_native"),
    RootSpec("src/codex_plugin_scanner/guard/native_resident_client.py", "native_resident_client_request"),
    RootSpec(
        "src/codex_plugin_scanner/guard/cli/commands_hook_native_authority.py",
        "try_native_hook_authority",
    ),
    RootSpec(
        "src/codex_plugin_scanner/guard/cli/commands_hook_native_authority.py",
        "try_native_or_source_ref_hook",
    ),
    _POSTURE_ROOT,
    *_CONFIG_SCOPE_ROOTS,
    RootSpec(
        "src/codex_plugin_scanner/guard/daemon/codex_native_live_decision.py", "complete_native_codex_live_decision"
    ),
)


def _read(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise RuntimeError(f"could not inspect {path}") from exc


def _relative(path: Path, root: Path) -> str:
    return path.relative_to(root).as_posix()


def _call_name(call: ast.Call) -> str | None:
    if isinstance(call.func, ast.Name):
        return call.func.id
    if isinstance(call.func, ast.Attribute):
        return call.func.attr
    return None


def _attribute_chain(value: ast.AST) -> tuple[str, ...]:
    if isinstance(value, ast.Name):
        return (value.id,)
    if isinstance(value, ast.Attribute):
        return (*_attribute_chain(value.value), value.attr)
    return ()


def _functions(tree: ast.AST, path: str) -> Iterable[FunctionRecord]:
    def visit(body: list[ast.stmt], prefix: str = "") -> Iterable[FunctionRecord]:
        for item in body:
            if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                qualname = f"{prefix}.{item.name}" if prefix else item.name
                yield FunctionRecord(path, item.name, qualname, item)
                yield from visit(item.body, qualname)
            elif isinstance(item, ast.ClassDef):
                class_prefix = f"{prefix}.{item.name}" if prefix else item.name
                yield from visit(item.body, class_prefix)

    if isinstance(tree, ast.Module):
        yield from visit(tree.body)


def _function_map(root: Path) -> dict[tuple[str, str], list[FunctionRecord]]:
    result: dict[tuple[str, str], list[FunctionRecord]] = {}
    source_root = root / "src/codex_plugin_scanner/guard"
    for path in sorted(source_root.rglob("*.py")):
        relative = _relative(path, root)
        tree = ast.parse(_read(path), filename=relative)
        for record in _functions(tree, relative):
            result.setdefault((relative, record.name), []).append(record)
    return result


def _root_record(root: Path, spec: RootSpec, records: dict[tuple[str, str], list[FunctionRecord]]) -> FunctionRecord:
    candidates = records.get((spec.path, spec.name), [])
    if spec.class_name is not None:
        candidates = [item for item in candidates if item.qualname.startswith(f"{spec.class_name}.")]
    if len(candidates) != 1:
        raise RuntimeError(f"expected one {spec.class_name or 'module'}.{spec.name} in {root / spec.path}")
    return candidates[0]


def _calls(record: FunctionRecord) -> tuple[str, ...]:
    names: list[str] = []
    for node in ast.walk(record.node):
        if not isinstance(node, ast.Call):
            continue
        if isinstance(node.func, ast.Name):
            names.append(node.func.id)
            continue
        if not isinstance(node.func, ast.Attribute):
            continue
        chain = _attribute_chain(node.func)
        if len(chain) == 2 and chain[0] in {"self", "cls"}:
            names.append(node.func.attr)
        elif len(chain) >= 2:
            # Keep qualified calls so the resolver can follow repository-module
            # aliases instead of silently dropping decision-critical helpers.
            names.append(".".join(chain))
    return tuple(names)


def _category(path: str, kind: str, function: str = "", operation: str = "") -> str:
    if path in _COMPATIBILITY_PATHS:
        return "compatibility_only"
    if path in _TRANSPORT_IDENTITY_PATHS:
        return "transport_identity"
    if path in _TRANSPORT_DECODE_PATHS and kind == "decode":
        return "transport_decode"
    scoped = scoped_io_category(path, kind, function, operation)
    if scoped is not None:
        return scoped
    if (
        path
        in {
            "src/codex_plugin_scanner/guard/native_decision_receipt.py",
            "src/codex_plugin_scanner/guard/native_command_observations.py",
        }
        and kind == "hash"
    ):
        return "transport_integrity"
    if path in _ASYNC_POLICY_PATHS:
        return "asynchronous_policy"
    if path.startswith(_PERSISTENCE_PATH_PREFIXES):
        return "persistence_only"
    if kind in {"archive", "decode"}:
        return "unclassified_python_content_io"
    return "unclassified_python_io"


def _observations(record: FunctionRecord) -> Iterable[IoObservation]:
    path = record.path
    if record.name in _EQUIVALENCE_FUNCTIONS:
        yield IoObservation(path, record.node.lineno, record.name, "equivalence", _category(path, "equivalence"), True)
    for node, function in scoped_nodes(record):
        if isinstance(node, ast.Call):
            name = _call_name(node)
            chain = _attribute_chain(node.func)
            kind: str | None = None
            operation: str | None = None
            if chain and chain[0] in _ARCHIVE_MODULES:
                kind, operation = "archive", name
            elif name in _FS_FUNCTIONS or name in _FS_METHODS:
                kind, operation = "filesystem", name
            elif name in _HASH_FUNCTIONS or (chain and chain[-2:] == ("hashlib", name)):
                kind, operation = "hash", name
            elif name in _DECODE_FUNCTIONS:
                kind, operation = "decode", name
            elif name in _ARCHIVE_MODULES:
                kind, operation = "archive", name
            if kind is not None and operation is not None:
                yield IoObservation(
                    path, node.lineno, operation, kind, _category(path, kind, function, operation), True
                )
        elif isinstance(node, ast.Import):
            for alias in node.names:
                module = alias.name.split(".", maxsplit=1)[0]
                if module in _ARCHIVE_MODULES:
                    yield IoObservation(path, node.lineno, module, "archive", _category(path, "archive"), True)
                elif module == "hashlib":
                    yield IoObservation(path, node.lineno, module, "hash", _category(path, "hash"), True)
        elif isinstance(node, ast.ImportFrom):
            module = (node.module or "").split(".", maxsplit=1)[0]
            if module in _ARCHIVE_MODULES:
                yield IoObservation(path, node.lineno, module, "archive", _category(path, "archive"), True)
            elif module == "hashlib":
                yield IoObservation(path, node.lineno, module, "hash", _category(path, "hash"), True)


def _reachable_records(
    root: Path,
    records: dict[tuple[str, str], list[FunctionRecord]],
    *,
    roots: tuple[RootSpec, ...] = ROOTS,
) -> tuple[FunctionRecord, ...]:
    pending = [_root_record(root, spec, records) for spec in roots]
    records_view = cast(Mapping[tuple[str, str], list[FunctionRecordLike]], records)
    seen: set[tuple[str, str]] = set()
    result: list[FunctionRecord] = []
    while pending:
        record = pending.pop()
        identity = (record.path, record.qualname)
        if identity in seen:
            continue
        seen.add(identity)
        result.append(record)
        for name in _calls(record):
            resolved = resolve_call(root, cast(FunctionRecordLike, cast(object, record)), name, records_view)
            if resolved is not None:
                pending.append(cast(FunctionRecord, cast(object, resolved)))
    return tuple(result)


def _call_in(node: ast.AST, name: str) -> bool:
    return any(isinstance(child, ast.Call) and _call_name(child) == name for child in ast.walk(node))


def _call_in_branch(node: ast.If, name: str) -> bool:
    """Inspect only the guarded body, never the compatibility ``else``."""
    return any(
        isinstance(child, ast.Call) and _call_name(child) == name
        for statement in node.body
        for child in ast.walk(statement)
    )


def _native_branch(record: FunctionRecord, marker: str) -> ast.If | None:
    for node in ast.walk(record.node):
        if not isinstance(node, ast.If):
            continue
        names = {child.id for child in ast.walk(node.test) if isinstance(child, ast.Name)}
        constants = {child.value for child in ast.walk(node.test) if isinstance(child, ast.Constant)}
        if marker in names or marker in constants:
            return node
    return None


def _branch_failures(root: Path, records: dict[tuple[str, str], list[FunctionRecord]]) -> list[str]:
    failures: list[str] = []
    review = _root_record(root, ROOTS[0], records)
    native = _native_branch(review, "auto")
    if native is None or not _call_in_branch(native, "_review_native_edge"):
        failures.append("HookWorker.review_http_payload has no direct auto/force native edge return")
    elif any(
        _call_in_branch(native, forbidden) for forbidden in ("load_guard_config", "review", "evaluate_source_file_ref")
    ):
        failures.append("HookWorker native PostTool branch reaches Python semantic evaluation")

    post = _root_record(root, ROOTS[1], records)
    required = _native_branch(post, "native_required")
    if required is None or not _call_in_branch(required, "review_post_tool_native"):
        failures.append("HookWorker PostTool native-required branch is incomplete")
    elif _call_in_branch(required, "review"):
        failures.append("HookWorker native-required branch calls Python review")

    publisher_path = "src/codex_plugin_scanner/guard/native_policy_snapshot_publisher.py"
    publisher = records.get((publisher_path, "start"), [])
    if len(publisher) != 1:
        failures.append("native policy publisher start function is missing")
    else:
        forbidden = (
            "_publication_context",
            "_compiled_effective_policy",
            "load_guard_config",
        )
        if any(_call_in(publisher[0].node, name) for name in forbidden):
            failures.append("policy publisher start performs decision-time config or secret I/O")
    return failures


def _inventory(
    root: Path,
    reachable: tuple[FunctionRecord, ...],
    posture: tuple[FunctionRecord, ...] = (),
) -> list[IoObservation]:
    reachable_ids = {(record.path, record.qualname) for record in reachable}
    posture_ids = {(record.path, record.qualname) for record in posture}
    observations: list[IoObservation] = []
    source_root = root / "src/codex_plugin_scanner/guard"
    for path in sorted(source_root.rglob("*.py")):
        relative = _relative(path, root)
        tree = ast.parse(_read(path), filename=relative)
        module_records = tuple(_functions(tree, relative))
        for record in module_records:
            for observation in _observations(record):
                category = observation.category
                if (record.path, record.qualname) in posture_ids and category == "asynchronous_policy":
                    category = "synchronous_posture_config"
                observations.append(
                    IoObservation(
                        observation.path,
                        observation.line,
                        observation.operation,
                        observation.kind,
                        category,
                        (record.path, record.qualname) in reachable_ids or relative in _COMPATIBILITY_PATHS,
                    )
                )
    return sorted(
        set(observations),
        key=lambda item: (item.path, item.line, item.operation, item.kind),
    )


def _capability_contract() -> list[dict[str, object]]:
    return capability_contract(COMPATIBILITY_MODES)


def validate(root: Path) -> dict[str, object]:
    root = root.resolve()
    records = _function_map(root)
    reachable = _reachable_records(root, records)
    posture = _reachable_records(root, records, roots=(_POSTURE_ROOT, *_CONFIG_SCOPE_ROOTS))
    failures = _branch_failures(root, records)
    inventory = _inventory(root, reachable, posture)
    reachable_bad = [item for item in inventory if item.reachable and item.category.startswith("unclassified_python")]
    if reachable_bad:
        failures.extend(
            f"reachable unclassified Python I/O: {item.path}:{item.line} {item.operation}" for item in reachable_bad
        )
    if failures:
        raise RuntimeError("; ".join(failures))
    reachable_inventory = [item for item in inventory if item.reachable]
    inventory_counts = Counter(item.category for item in inventory)
    return {
        "schema": SCHEMA,
        "status": "passed",
        "native_modes": sorted(NATIVE_MODES),
        "compatibility_modes": sorted(COMPATIBILITY_MODES),
        "capabilities": _capability_contract(),
        "roots": [f"{item.path}:{item.name}" for item in (_root_record(root, spec, records) for spec in ROOTS)],
        "reachable_function_count": len(reachable),
        "inventory_total": len(inventory),
        "inventory_by_category": dict(sorted(inventory_counts.items())),
        "inventory": [
            {
                "path": item.path,
                "line": item.line,
                "operation": item.operation,
                "kind": item.kind,
                "category": item.category,
                "reachable": item.reachable,
            }
            for item in reachable_inventory
        ],
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument("--json", type=Path)
    args = parser.parse_args(argv)
    payload = validate(args.root)
    rendered = json.dumps(payload, indent=2, sort_keys=True)
    print(rendered)
    if args.json is not None:
        args.json.parent.mkdir(parents=True, exist_ok=True)
        args.json.write_text(rendered + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

