"""Argument handling for the private installed SLO daemon fixture."""

from __future__ import annotations

import sys
from collections.abc import Callable, Mapping
from pathlib import Path
from typing import Protocol

from scripts.native_slo_failure import failure_evidence


class _Serve(Protocol):
    def __call__(
        self, runtime: Path, setup: str, policy: str, workspace_count: int | None, *, native_phases: bool
    ) -> int: ...


def main(serve: _Serve, emit: Callable[[Mapping[str, object]], None]) -> int:
    try:
        arguments = sys.argv[1:]
        native_phases = bool(arguments and arguments[-1] == "--native-phases")
        if native_phases:
            arguments.pop()
        if len(arguments) not in {4, 5} or arguments[0] != "--serve":
            raise ValueError("private daemon fixture invocation required")
        return serve(
            Path(arguments[1]).resolve(strict=True),
            arguments[2],
            arguments[3],
            int(arguments[4]) if len(arguments) == 5 else None,
            native_phases=native_phases,
        )
    except Exception as error:
        emit({"error": "fixture_failed", "detail": failure_evidence(error)})
        return 1

"""Keep private fixture attempt labels separate from opaque harness IDs."""

from __future__ import annotations

import re
from collections.abc import Mapping
from uuid import uuid4

from scripts.native_slo_adapter import payload

_ATTEMPT = re.compile(r"^mixed-(?:load|policy|recovery)-[0-9]{1,6}$")
_NATIVE_FIELDS = {"claude-code": "tool_use_id", "codex": "tool_call_id"}


def attempt_label(value: object) -> str | None:
    return value if isinstance(value, str) and _ATTEMPT.fullmatch(value) is not None else None


def request_attempt(request: object) -> str | None:
    if not isinstance(request, Mapping):
        return None
    return attempt_label(request.get("native_slo_attempt"))


def fixture_request(
    harness: str,
    event: str,
    size_class: str = "1k",
    *,
    attempt: str,
    request_payload: Mapping[str, object] | None = None,
) -> dict[str, object]:
    if harness not in _NATIVE_FIELDS or attempt_label(attempt) is None:
        raise ValueError("mixed fixture request identity outside declared scope")
    return {
        **(payload(event, size_class) if request_payload is None else request_payload),
        "native_slo_attempt": attempt,
        # Each harness receives its real native field and fresh randomness.
        # A readable counter belongs only to diagnostic joins, never to the
        # production strong-identifier input or a fabricated receipt.
        _NATIVE_FIELDS[harness]: f"fixture-{uuid4().hex}",
    }

"""Private mixed-scenario controls for an actual installed daemon fixture.

Controls use production settings, policy publication, inventory persistence and
resident containment. Enforcing probes use authenticated HTTP, just like load
requests. This module does not construct snapshots or native decision receipts.
"""

from __future__ import annotations

import hashlib
import time
from collections.abc import Mapping
from datetime import datetime, timezone
from typing import TYPE_CHECKING, Any

from scripts.native_slo_contract import MAX_READINESS_P95_MS
from scripts.native_slo_mixed_request import fixture_request
from scripts.native_slo_mixed_response import delivered_decision
from scripts.native_slo_mixed_witness import MAX_CONTROL_ACTIONS, ReceiptWitness, writer_drained

if TYPE_CHECKING:
    from codex_plugin_scanner.guard.daemon.runtime_hook_evidence_queue_observation import EvidenceQueueObservation
    from scripts.native_slo_sqlite_vfs import SQLiteVFSObservation


class MixedScenarioFixture:
    def __init__(
        self,
        session: Any,
        *,
        queue_observation: EvidenceQueueObservation | None = None,
        sqlite_observer: SQLiteVFSObservation | None = None,
    ) -> None:
        self.session = session
        self.queue_observation = queue_observation
        self.sqlite_observer = sqlite_observer
        self.witness: ReceiptWitness | None = None
        self.samples = 0
        self.peaks: dict[str, int | float] = {}
        self.started = 0.0
        self.last_sample = 0.0
        self.max_sample_gap_ms = 0.0
        self.initial: dict[str, Any] = {}
        self.actions = 0
        self.finished = False
        self.progress: dict[str, object] = {}

    def close(self) -> None:
        try:
            if self.witness is not None:
                self.witness.close()
        finally:
            if self.sqlite_observer is not None:
                self.sqlite_observer.close()

    def dispatch(self, operation: str, request: Mapping[str, Any]) -> dict[str, object]:
        # Failure remains an explicit control outcome, so later work and receipt
        # reconciliation can still be collected after a failed mutation/restart.
        self.progress = {}
        try:
            return {"status": "completed", **self._dispatch(operation, request)}
        except Exception as error:
            return {"status": "failed", "failure_type": type(error).__name__, **self.progress}

    def _dispatch(self, operation: str, request: Mapping[str, Any]) -> dict[str, object]:
        if operation == "mixed_start" and self.witness is None:
            worker = self.session.daemon._server.hook_worker
            if worker.test_oracle is not None:
                raise RuntimeError("mixed requires installed native authority")
            self._ack("allow", previous_generation=0)
            queue_observation, sqlite_observer = self.queue_observation, self.sqlite_observer
            if "receipt_observation" in request:
                from scripts.native_slo_persistence_observation import PersistenceObservationSpec

                if self.queue_observation is not None or self.sqlite_observer is not None:
                    raise RuntimeError("mixed persistence observation already supplied")
                if request.get("receipt_profile", "candidate") != "candidate":
                    raise ValueError("persistence observation requires the candidate receipt contract")
                spec = PersistenceObservationSpec.from_request(request["receipt_observation"])
                queue_observation, sqlite_observer = spec.create(self.session)
            try:
                witness = ReceiptWitness(
                    self.session,
                    maximum=int(request["maximum"]),
                    receipt_profile=str(request.get("receipt_profile", "candidate")),
                    queue_observation=queue_observation,
                    sqlite_observer=sqlite_observer,
                ).__enter__()
            except BaseException:
                if sqlite_observer is not None:
                    try:
                        sqlite_observer.close()
                    except BaseException:
                        self.progress["observation_cleanup_failed"] = True
                raise
            self.queue_observation, self.sqlite_observer, self.witness = queue_observation, sqlite_observer, witness
            self.started = self.last_sample = time.monotonic()
            self.initial = self._stats()
            return self.sample()
        if self.witness is None:
            raise RuntimeError("mixed scenario has not started")
        if operation == "mixed_page":
            if not self.finished:
                raise RuntimeError("mixed pages require completed collection")
            return self.witness.page(int(request["offset"]), int(request.get("limit", 128)))
        if self.finished:
            raise RuntimeError("mixed scenario already finished")
        if operation == "mixed_sample":
            return self.sample()
        if operation == "mixed_finish":
            deadline = time.monotonic() + 5.0
            while True:
                result = self.sample()
                stats = result["writer"]
                assert isinstance(stats, dict)
                if writer_drained(stats):
                    break
                if time.monotonic() >= deadline:
                    break
                time.sleep(0.025)
            self.witness.reconcile(verify_all=True)
            self.finished = True
            self.close()
            result["receipts"] = self.witness.report()
            return result
        self.actions += 1
        if self.actions > MAX_CONTROL_ACTIONS:
            raise ValueError("mixed control action bound exceeded")
        index = int(request["index"])
        if not 0 <= index < MAX_CONTROL_ACTIONS:
            raise ValueError("mixed control index outside bound")
        if operation == "mixed_policy":
            return self.policy(str(request["action"]), index)
        if operation == "mixed_restart":
            return self.restart(index)
        if operation == "mixed_inventory":
            return self.inventory(index, int(request.get("count", 32)))
        raise ValueError("unsupported mixed operation")

    def _stats(self) -> dict[str, Any]:
        server = self.session.daemon._server
        writer = server.runtime_hook_evidence_writer
        # Both pinned versions use a Condition with its default reentrant lock.
        # Read the live batch flag with the corresponding public counters.
        with writer._condition:
            writer_stats = {**writer.stats(), "in_flight": writer._in_flight}
        return {
            "scheduler": server.runtime_hook_scheduler.stats(),
            "writer": writer_stats,
        }

    def sample(self) -> dict[str, object]:
        assert self.witness is not None
        self.witness.reconcile()
        now = time.monotonic()
        self.max_sample_gap_ms = max(self.max_sample_gap_ms, (now - self.last_sample) * 1000)
        self.last_sample = now
        self.samples += 1
        stats = self._stats()
        for section, keys in (
            ("scheduler", ("active", "queued", "retained_bytes", "oldest_queued_ms")),
            ("writer", ("queued", "queued_bytes", "durable_pending", "receipt_durable_pending")),
        ):
            for key in keys:
                value = stats[section].get(key)
                if isinstance(value, (int, float)):
                    name = f"{section}_{key}"
                    self.peaks[name] = max(self.peaks.get(name, 0), value)
        return {
            **stats,
            "initial": self.initial,
            "sampled_peaks": dict(self.peaks),
            "sample_count": self.samples,
            "max_sample_gap_ms": self.max_sample_gap_ms,
            "elapsed_ms": (now - self.started) * 1000,
            "receipts": self.witness.report(),
        }

    def _ack(self, action: str, *, previous_generation: int) -> dict[str, Any]:
        from codex_plugin_scanner.guard.native_policy_snapshot_acked import acked_snapshot_binding_for_store

        worker = self.session.daemon._server.hook_worker
        deadline = time.monotonic() + MAX_READINESS_P95_MS / 1000
        while True:
            prepared = worker.prepare_workspace_policy(self.session.workspace, deadline=deadline)
            snapshot = worker.policy_snapshot_publisher.current_snapshot()
            persisted = acked_snapshot_binding_for_store(self.session.store)
            effective = snapshot.get("effective_policy") if isinstance(snapshot, dict) else None
            if (
                time.monotonic() <= deadline
                and isinstance(prepared, dict)
                and isinstance(snapshot, dict)
                and isinstance(persisted, dict)
                and isinstance(effective, dict)
                and snapshot.get("mode") == "enforce"
                and effective.get("default_action") == action
                and effective.get("subprocess_action") == action
                and isinstance(prepared.get("generation"), int)
                and prepared["generation"] > previous_generation
                and all(
                    prepared.get(key) == snapshot.get(key) == persisted.get(key)
                    for key in ("generation", "policy_digest", "runtime_identity")
                )
            ):
                return prepared
            if time.monotonic() >= deadline:
                raise RuntimeError("mixed policy acknowledgment deadline")
            time.sleep(0.005)

    def _probe(
        self, kind: str, index: int, binding: Mapping[str, Any], action: str, accepted: float
    ) -> dict[str, object]:
        from scripts.native_slo_session import _request

        assert self.witness is not None
        attempt = f"mixed-{kind}-{index}"
        request = fixture_request("claude-code", "PreToolUse", attempt=attempt)
        response = _request(
            self.session.daemon,
            guard_home=self.session.guard_home,
            workspace=self.session.workspace,
            harness="claude-code",
            request_payload=request,
        )
        row = self.witness.row(attempt)
        expected_decision = "allow" if action == "allow" else "deny"
        enforced = (
            row is not None
            and row["policy_generation"] == binding["generation"]
            and row["policy_digest"] == binding["policy_digest"]
            and row["policy_action"] == action
            and row["decision"] == expected_decision
            and delivered_decision("PreToolUse", response) == expected_decision
        )
        first = self.witness.first_decision(binding, action, since=accepted)
        return {
            "attempt": attempt,
            "first_enforcing_receipt": enforced,
            "accept_to_probe_response_ms": (time.monotonic() - accepted) * 1000,
            "first_decision_attempt": first["attempt"] if first is not None else None,
            "accept_to_first_decision_ms": first["native_finished_ms"] - (accepted - self.witness.started) * 1000
            if first is not None
            else None,
            "generation": binding["generation"],
            "policy_digest": binding["policy_digest"],
            "expected_action": action,
            "probe_has_native_receipt": row is not None,
        }

    def policy(self, action: str, index: int) -> dict[str, object]:
        from codex_plugin_scanner.guard.config import update_guard_settings

        if action not in {"allow", "block"}:
            raise ValueError("mixed policy action unsupported")
        worker = self.session.daemon._server.hook_worker
        prior = worker.policy_snapshot_publisher.current_snapshot_binding()
        if not isinstance(prior, dict):
            raise RuntimeError("mixed prior policy unavailable")
        started = time.monotonic()
        self.progress = {
            "kind": "policy",
            "mutation_attempted": True,
            "mutation_returned": False,
            "acknowledged": False,
        }
        # This is the public settings API, including its normal approval gate.
        # The fixture owns a fresh private home; no gate override is supplied.
        update_guard_settings(self.session.guard_home, {"default_action": action, "subprocess_action": action})
        accepted = time.monotonic()
        self.progress.update(mutation_returned=True, mutation_ms=(accepted - started) * 1000)
        binding = self._ack(action, previous_generation=int(prior["generation"]))
        acked = time.monotonic()
        self.progress.update(acknowledged=True, accept_to_ack_ms=(acked - accepted) * 1000)
        return {
            "kind": "policy",
            "mutation_ms": (accepted - started) * 1000,
            "accept_to_ack_ms": (acked - accepted) * 1000,
            **self._probe("policy", index, binding, action, accepted),
        }

    def restart(self, index: int) -> dict[str, object]:
        worker = self.session.daemon._server.hook_worker
        snapshot = worker.policy_snapshot_publisher.current_snapshot()
        if not isinstance(snapshot, dict):
            raise RuntimeError("mixed recovery has no acknowledged policy")
        action = snapshot["effective_policy"]["default_action"]
        started = time.monotonic()
        self.progress = {"kind": "resident_recovery", "contained": False, "python_process_restarted": False}
        contained = self.session.stop_resident()
        if not contained:
            raise RuntimeError("mixed resident containment failed")
        self.progress["contained"] = True
        binding = self._ack(action, previous_generation=0)
        return {
            "kind": "resident_recovery",
            "contained": True,
            "python_process_restarted": False,
            **self._probe("recovery", index, binding, action, started),
        }

    def inventory(self, index: int, count: int) -> dict[str, object]:
        from codex_plugin_scanner.guard.models import GuardArtifact

        if not 1 <= count <= 128:
            raise ValueError("mixed inventory batch outside bound")
        started = time.monotonic()
        self.progress = {"kind": "local_inventory_upsert", "offered": count, "attempted": 0, "committed": 0}
        for item in range(count):
            self.progress["attempted"] = item + 1
            body = f"mixed local inventory revision {index}:{item}\n".encode("ascii")
            path = self.session.workspace / f"mixed-inventory-{item}.txt"
            path.write_bytes(body)
            artifact = GuardArtifact(
                artifact_id=f"mixed-inventory-{item}",
                name="Mixed inventory fixture",
                harness="codex",
                artifact_type="skill",
                source_scope="workspace",
                config_path=str(path),
            )
            self.session.store.record_inventory_artifact(
                artifact=artifact,
                artifact_hash=hashlib.sha256(path.read_bytes()).hexdigest(),
                policy_action="review",
                changed=True,
                now=datetime.now(timezone.utc).isoformat(),
                approved=False,
            )
            self.progress["committed"] = item + 1
        return {**self.progress, "elapsed_ms": (time.monotonic() - started) * 1000}

"""Bounded Linux process witnesses for the native diagnostic receiver.

This binds a live, explicitly owned fixture descendant at observation time.
It is diagnostic attribution, not a general concurrent-process attestation.
No command line, path, environment or credential bytes enter exported reports.
"""

from __future__ import annotations

import hashlib
import os
import stat
from dataclasses import dataclass
from pathlib import Path

from scripts.native_slo_rust_phase_schema import ROLES

MAX_PROCESS_DEPTH = 16
MAX_EXECUTABLE_BYTES = 128 * 1024 * 1024


@dataclass(frozen=True)
class ProcessIdentity:
    pid: int
    parent: int
    group: int
    session: int
    start_ticks: int


def _refuse() -> None:
    raise ValueError("native_phase_process_refused")


def _read_at(directory: int, name: str, bound: int) -> bytes:
    descriptor = os.open(name, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW, dir_fd=directory)
    try:
        chunks: list[bytes] = []
        remaining = bound + 1
        while remaining:
            chunk = os.read(descriptor, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        value = b"".join(chunks)
        if len(value) > bound:
            _refuse()
        return value
    finally:
        os.close(descriptor)


def parse_stat(value: bytes, expected_pid: int) -> ProcessIdentity:
    text = value.decode("utf-8")
    head, fields_text = text.rsplit(") ", 1)
    pid = int(head.split(" (", 1)[0])
    fields = fields_text.split()
    if pid != expected_pid or len(fields) < 20 or fields[0] in {"Z", "X", "x"}:
        _refuse()
    row = ProcessIdentity(pid, int(fields[1]), int(fields[2]), int(fields[3]), int(fields[19]))
    if row.pid <= 0 or row.parent < 0 or row.group <= 0 or row.session <= 0 or row.start_ticks <= 0:
        _refuse()
    return row


def _same_executable(metadata: os.stat_result) -> tuple[int, int, int, int, int, int]:
    return (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
        metadata.st_ctime_ns,
    )


class Executable:
    """Retain the exact caller-supplied binary descriptor and its source digest."""

    def __init__(self, path: Path) -> None:
        self.descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
        try:
            before = os.fstat(self.descriptor)
            if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= MAX_EXECUTABLE_BYTES:
                _refuse()
            digest = hashlib.sha256()
            count = 0
            while True:
                chunk = os.read(self.descriptor, min(65536, MAX_EXECUTABLE_BYTES + 1 - count))
                if not chunk:
                    break
                count += len(chunk)
                digest.update(chunk)
                if count > MAX_EXECUTABLE_BYTES:
                    _refuse()
            self.identity = _same_executable(before)
            if count != before.st_size or _same_executable(os.fstat(self.descriptor)) != self.identity:
                _refuse()
            self.sha256 = digest.hexdigest()
        except BaseException:
            os.close(self.descriptor)
            self.descriptor = -1
            raise

    def current(self) -> bool:
        return self.descriptor >= 0 and _same_executable(os.fstat(self.descriptor)) == self.identity

    def close(self) -> None:
        if self.descriptor >= 0:
            os.close(self.descriptor)
            self.descriptor = -1


def read_process(pid: int, executable: Executable | None = None) -> tuple[ProcessIdentity, str | None]:
    if type(pid) is not int or not 1 <= pid <= 2**31 - 1:
        _refuse()
    directory = os.open(f"/proc/{pid}", os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        before = parse_stat(_read_at(directory, "stat", 4096), pid)
        status = _read_at(directory, "status", 65536).decode("ascii")
        uid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Uid:")]
        gid_rows = [line.split()[1:] for line in status.splitlines() if line.startswith("Gid:")]
        if (
            len(uid_rows) != 1
            or len(gid_rows) != 1
            or uid_rows[0] != [str(os.geteuid())] * 4
            or gid_rows[0] != [str(os.getegid())] * 4
        ):
            _refuse()
        role = None
        if executable is not None:
            if not executable.current() or _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
                _refuse()
            command = _read_at(directory, "cmdline", 16384)
            parts = command.split(b"\0")
            if len(parts) < 3 or parts[-1] != b"":
                _refuse()
            role = ROLES.get(parts[1].decode("ascii"))
            if role is None:
                _refuse()
        after = parse_stat(_read_at(directory, "stat", 4096), pid)
        if before != after:
            _refuse()
        if executable is not None and _same_executable(os.stat("exe", dir_fd=directory)) != executable.identity:
            _refuse()
        return before, role
    finally:
        os.close(directory)


class OwnedCohort:
    def __init__(self, fixture_pid: int, executable: Executable) -> None:
        root, _ = read_process(fixture_pid)
        if root.parent != os.getpid() or root.session != root.pid or root.group != root.pid:
            _refuse()
        self.root = root
        self.executable = executable
        self.seen: dict[int, tuple[int, str]] = {}

    def admit(self, pid: int, start_ticks: int, role: str) -> ProcessIdentity:
        sender, actual_role = read_process(pid, self.executable)
        if sender.start_ticks != start_ticks or actual_role != role:
            _refuse()
        if pid in self.seen and self.seen[pid] != (start_ticks, role):
            _refuse()
        if pid not in self.seen and len(self.seen) >= 16:
            _refuse()
        chain = [sender]
        for _ in range(MAX_PROCESS_DEPTH):
            current = chain[-1]
            if current.pid == self.root.pid:
                break
            if current.parent <= 1 or any(row.pid == current.parent for row in chain):
                _refuse()
            parent, _ = read_process(current.parent)
            if parent.start_ticks > current.start_ticks:
                _refuse()
            chain.append(parent)
        if chain[-1] != self.root:
            _refuse()
        # Re-read each exact process generation after walking the ancestry.
        # Any exit, reparenting or reuse makes this observation unavailable.
        for original in reversed(chain):
            current, _ = read_process(original.pid, self.executable if original.pid == sender.pid else None)
            if current != original:
                _refuse()
        self.seen[pid] = (start_ticks, role)
        return sender

