def measure_native_phases(runtime: Path, count: int, evidence_file: Path) -> dict[str, Any]:
    if type(count) is not int or not 1 <= count <= 100:
        raise ValueError("native_phase_count_outside_original_bound")
    result: dict[str, Any] = {
        "schema": "hol-guard-native-and-python-phase-run.v1",
        "scope": "diagnostic_instrumented_existing_installed_workload",
        "headline_timing_eligible": False,
        "qualification_complete": False,
        "complete_run": False,
        "status": "platform_unsupported",
        "workload_passed": False,
        "workload_failure_observed": False,
        "workload_started": False,
        "existing_fixture_failure_observed": False,
        "native_phase_error_observed": False,
        "original_phase_count_bound": 100,
        "requested_count_per_case": count,
        "original_semantic_workload": None,
        "native": None,
    }
    if not supported():
        return result
    receiver: NativePhaseReceiver | None = None
    try:
        receiver = NativePhaseReceiver(runtime)
    except Exception:
        result["native_phase_error_observed"] = True
    try:
        if receiver is not None:
            try:
                with DaemonFixture(
                    runtime, setup="normal", _native_phase_environment=receiver.environment()
                ) as session:
                    try:
                        receiver.attach(session.pid)
                    except Exception:
                        result["native_phase_error_observed"] = True
                    else:
                        result["workload_started"] = True
                        try:
                            result["original_semantic_workload"] = measure_installed_phases(
                                session, count, evidence_file
                            )
                            result["workload_passed"] = True
                        except Exception:
                            # The existing journal retains original failures;
                            # never export an exception or request value here.
                            result["workload_failure_observed"] = True
            except Exception:
                result["existing_fixture_failure_observed"] = True
    finally:
        if receiver is not None:
            try:
                receiver.close()
                result["native"] = receiver.report()
            except Exception:
                result["native_phase_error_observed"] = True
    native = cast(dict[str, Any] | None, result["native"])
    if result["existing_fixture_failure_observed"]:
        result["status"] = "existing_fixture_failed"
    elif result["workload_failure_observed"]:
        result["status"] = "workload_failed"
    elif not result["workload_started"]:
        result["status"] = "diagnostic_setup_failed"
    elif native is None or result["native_phase_error_observed"]:
        result["status"] = "diagnostic_incomplete"
    elif _REQUIRED_PHASES <= _observed_phases(native) and any(  # noqa: SIM300 - preserve operand evaluation order
        phase["phase"] in {"unix_socket_creation", "loopback_connect_handle"}
        and phase["statistics"] is not None
        and phase["statistics"]["returned_ok"] > 0
        for process in native["processes"]
        if process["snapshot"] is not None
        for phase in process["snapshot"]["phases"]
    ):
        result["status"] = "diagnostic_phases_observed"
    else:
        result["status"] = "diagnostic_incomplete"
    return result


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--runtime", type=Path, required=True)
    parser.add_argument("--count", type=int, default=1)
    parser.add_argument("--evidence-file", type=Path, required=True)
    parser.add_argument("--json", type=Path, required=True)
    arguments = parser.parse_args()
    report = measure_native_phases(arguments.runtime.resolve(strict=True), arguments.count, arguments.evidence_file)
    rendered = json.dumps(report, sort_keys=True, indent=2) + "\n"
    if len(rendered.encode("utf-8")) > 1024 * 1024:
        raise ValueError("native_phase_report_exceeded_bound")
    with arguments.json.open("x", encoding="utf-8") as output:
        output.write(rendered)
    print(
        json.dumps(
            {
                "schema": report["schema"],
                "status": report["status"],
                "headline_timing_eligible": False,
                "qualification_complete": False,
            },
            sort_keys=True,
        )
    )
    return 0 if report["status"] == "diagnostic_phases_observed" else 2


if __name__ == "__main__":
    raise SystemExit(main())

"""Descriptor-pinned extension admission and bounded runtime image identities."""

from __future__ import annotations

import contextlib
import hashlib
import os
import re
import stat
from pathlib import Path
from typing import Any

MAX_IMAGE_BYTES = 64 * 1024 * 1024


def _read_identity(descriptor: int, *, owned: bool) -> dict[str, Any]:
    before = os.fstat(descriptor)
    if not stat.S_ISREG(before.st_mode) or not 0 < before.st_size <= MAX_IMAGE_BYTES:
        raise ValueError("runtime image must be a bounded regular file")
    if owned and (before.st_uid != os.getuid() or before.st_nlink != 1 or before.st_mode & 0o022):
        raise ValueError("extension must be an exclusively owned, non-writable-by-others image")
    digest = hashlib.sha256()
    count = 0
    while block := os.read(descriptor, 65_536):
        count += len(block)
        if count > MAX_IMAGE_BYTES:
            raise ValueError("runtime image read bound exceeded")
        digest.update(block)
    after = os.fstat(descriptor)
    fields = ("st_dev", "st_ino", "st_size", "st_mtime_ns", "st_ctime_ns", "st_mode", "st_uid", "st_nlink")
    if count != before.st_size or any(getattr(before, key) != getattr(after, key) for key in fields):
        raise ValueError("runtime image changed during descriptor read")
    os.lseek(descriptor, 0, os.SEEK_SET)
    return {
        "sha256": digest.hexdigest(),
        "bytes": count,
        "device": before.st_dev,
        "inode": before.st_ino,
        "mode": stat.S_IMODE(before.st_mode),
        "mtime_ns": before.st_mtime_ns,
        "ctime_ns": before.st_ctime_ns,
    }


def image_identity(path: Path) -> dict[str, Any]:
    descriptor = os.open(path.resolve(strict=True), os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        return _read_identity(descriptor, owned=False)
    finally:
        os.close(descriptor)


@contextlib.contextmanager
def pinned_extension(path: Path, *, expected_sha256: str) -> Any:
    if re.fullmatch("[0-9a-f]{64}", expected_sha256) is None:
        raise ValueError("exact extension SHA256 is required")
    descriptor = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        identity = _read_identity(descriptor, owned=True)
        if identity["bytes"] > 8 * 1024 * 1024:
            raise ValueError("extension exceeds the 8 MiB image bound")
        if identity["sha256"] != expected_sha256:
            raise ValueError("extension content does not match the admitted SHA256")
        yield descriptor, identity
        after = _read_identity(descriptor, owned=True)
        if after != identity:
            raise ValueError("extension identity changed during observation")
    finally:
        os.close(descriptor)


def code_mapping(address: str) -> dict[str, Any]:
    """Read only the exact executable mapping containing the reported C callback."""
    if re.fullmatch(r"0x[0-9a-f]{1,16}", address) is None:
        raise ValueError("invalid callback address")
    value = int(address, 16)
    maps = Path("/proc/self/maps").read_bytes()
    if len(maps) > 4 * 1024 * 1024:
        raise ValueError("process mapping metadata exceeds its observation bound")
    matches = []
    for raw in maps.decode("utf-8", errors="strict").splitlines():
        fields = raw.split(maxsplit=5)
        if len(fields) < 5:
            raise ValueError("invalid process mapping metadata")
        start, end = (int(part, 16) for part in fields[0].split("-"))
        if start <= value < end:
            major, minor = (int(part, 16) for part in fields[3].split(":"))
            matches.append(
                {
                    "device": os.makedev(major, minor),
                    "inode": int(fields[4]),
                    "permissions": fields[1],
                    "file_offset": int(fields[2], 16),
                }
            )
    if len(matches) != 1 or "x" not in matches[0]["permissions"] or "w" in matches[0]["permissions"]:
        raise ValueError("callback lacks one non-writable executable file mapping")
    if matches[0]["inode"] == 0:
        raise ValueError("anonymous callback mappings are outside observation admission")
    return matches[0]


def already_mapped(identity: dict[str, Any]) -> bool:
    maps = Path("/proc/self/maps").read_bytes()
    if len(maps) > 4 * 1024 * 1024:
        raise ValueError("process mapping metadata exceeds its observation bound")
    for raw in maps.decode("utf-8", errors="strict").splitlines():
        fields = raw.split(maxsplit=5)
        if len(fields) < 5:
            raise ValueError("invalid process mapping metadata")
        major, minor = (int(part, 16) for part in fields[3].split(":"))
        if os.makedev(major, minor) == identity["device"] and int(fields[4]) == identity["inode"]:
            return True
    return False

"""Bounded Linux poststart workspace and same-home service replacement diagnostic.

Initial compilation is excluded. The two service instances share one Python
process and one owned home. Full typed observations stay in the private ledger;
this diagnostic does not provide installed SLO or platform qualification.
"""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path
from typing import Any

if __package__ in {None, ""}:
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from scripts.bench_guard_native_installed_slo_runtime import _clear_proof_overrides, _runtime_summary
from scripts.native_slo_workspace_poststart_evidence import RetainedLedger, encode_retained
from scripts.native_slo_workspace_poststart_observation import PostStartObservation, stricter_overlay
from scripts.native_slo_workspace_poststart_session import COUNTS, PersistentWorkspaceHome, diagnostic_failure
from scripts.native_slo_workspace_trace import validate_trace


def service(home: PersistentWorkspaceHome, ordinal: int, ledger: RetainedLedger) -> dict[str, Any]:
    count = len(home.workspaces)
    result: dict[str, Any] = {
        "index": ordinal,
        "status": "offered",
        "passed": False,
        "phase_results": [],
        "qualification_complete": False,
    }
    session = observation = None
    try:
        if not ledger.write(
            {
                "kind": "poststart_service_offer",
                "registered_workspaces": count,
                "instance": ordinal,
            }
        ):
            raise RuntimeError("poststart service offer retention unavailable")
        session = home.start_instance()
        result["status"] = "constructed"
        result["ready"] = session.ready()
        result["status"] = "ready"
        phases = ("poststart_registration", "public_policy") if ordinal == 0 else ("explicit_reregistration",)
        observation = PostStartObservation(session, instance=ordinal)
        with observation:
            for name in phases:
                phase: dict[str, Any] = {"name": name, "status": "offered", "passed": False}
                result["phase_results"].append(phase)
                try:
                    if not ledger.write(
                        {
                            "kind": "poststart_phase_offer",
                            "registered_workspaces": count,
                            "instance": ordinal,
                            "phase": name,
                        }
                    ):
                        raise RuntimeError("poststart phase offer retention unavailable")
                    phase.update(observation.phase(name))
                except BaseException as error:
                    phase.update(status="failed", failure=diagnostic_failure(error))
                finally:
                    ledger.write(
                        {
                            "kind": "poststart_phase_terminal",
                            "registered_workspaces": count,
                            "instance": ordinal,
                            "phase": phase,
                        }
                    )
                if phase["passed"] is not True:
                    break
        if observation.final is None:
            raise RuntimeError("poststart observer final record is missing")
        for row in observation.final["rows"]:
            ledger.write(
                {
                    "kind": "poststart_publisher_event",
                    "registered_workspaces": count,
                    "instance": ordinal,
                    "event": row,
                }
            )
        validate_trace(observation.final["rows"], observation.final["observer"])
    except BaseException as error:
        result["failure"] = diagnostic_failure(error)
    finally:
        if observation is not None:
            if observation.final is None:
                try:
                    observation.close()
                except BaseException as error:
                    result["observation_final_failure"] = diagnostic_failure(error)
            result["observation"] = observation.final
        if session is not None:
            try:
                result["retirement"] = session.stop()
            except BaseException as error:
                result["retirement"] = {
                    "passed": False,
                    "status": "stop_observation_incomplete",
                    "retained": session.retirement,
                    "failure": diagnostic_failure(error),
                }
        else:
            result["retirement"] = {"passed": False, "status": "construction_not_complete"}
        result["status"] = "finished"
        result["passed"] = (
            "failure" not in result
            and "observation_final_failure" not in result
            and observation is not None
            and observation.final is not None
            and observation.final["passed"] is True
            and result["retirement"]["passed"] is True
            and not ledger.errors
        )
        try:
            ledger.write(
                {
                    "kind": "poststart_service_terminal",
                    "registered_workspaces": count,
                    "instance": result,
                }
            )
        except BaseException as error:
            result.update(passed=False, retention_failure=diagnostic_failure(error))
    return result


def cell(runtime: Path, count: int, ledger: RetainedLedger) -> dict[str, Any]:
    result: dict[str, Any] = {
        "registered_workspaces": count,
        "passed": False,
        "instances": [],
        "qualification_complete": False,
        "scope": "poststart registration and same-process service replacement on one owned home",
    }
    home = None
    try:
        if not ledger.write({"kind": "poststart_cell_offer", "registered_workspaces": count}):
            raise RuntimeError("poststart cell offer retention unavailable")
        home = PersistentWorkspaceHome(runtime, count)
        for ordinal in (0, 1):
            if ordinal == 1:
                result["stricter_overlay"] = stricter_overlay(home)
                ledger.write(
                    {
                        "kind": "poststart_stricter_overlay",
                        "registered_workspaces": count,
                        **result["stricter_overlay"],
                    }
                )
            instance = service(home, ordinal, ledger)
            result["instances"].append(instance)
            if instance["passed"] is not True:
                break
        result["passed"] = len(result["instances"]) == 2 and all(row["passed"] is True for row in result["instances"])
    except BaseException as error:
        result.update(passed=False, failure=diagnostic_failure(error))
    finally:
        if home is not None:
            try:
                result["home_cleanup"] = home.finish()
                if result["home_cleanup"]["contained"] is not True:
                    result["passed"] = False
            except BaseException as error:
                result["passed"] = False
                result["home_cleanup_failure"] = diagnostic_failure(error)
        else:
            result["home_cleanup"] = {
                "contained": False,
                "status": "home_construction_not_complete",
                "root_removal_observed": False,
            }
        result["unoffered_service_instances"] = 2 - len(result["instances"])
        result["unconstructed_service_instances"] = 2 - (len(home.instances) if home is not None else 0)
        try:
            ledger.write(
                {
                    "kind": "poststart_cell_terminal",
                    "registered_workspaces": count,
                    "passed": result["passed"],
                    "result": result,
                }
            )
        except BaseException as error:
            result.update(passed=False, retention_failure=diagnostic_failure(error))
    return result


def run(runtime: Path, *, raw_file: Path, counts: tuple[int, ...] = COUNTS) -> dict[str, Any]:
    if sys.flags.optimize:
        raise ValueError("poststart diagnostic requires active invariant checks")
    if counts != COUNTS:
        raise ValueError("poststart diagnostic requires the complete ordered 1/10/100 matrix")
    _clear_proof_overrides()
    identity = _runtime_summary(runtime)
    ledger = RetainedLedger(raw_file)
    cells = []
    failure = None
    try:
        ledger.write(
            {
                "kind": "poststart_matrix_offer",
                "counts": counts,
                "identity": identity,
                "qualification_complete": False,
            }
        )
        for count in counts:
            observed = cell(runtime, count, ledger)
            cells.append(observed)
            if observed["passed"] is not True or ledger.errors:
                break
    except BaseException as error:
        failure = diagnostic_failure(error)
    finally:
        raw = ledger.finish()
    result = {
        "scope": "bounded Linux poststart workspace observation",
        "identity": identity,
        "declared_counts": counts,
        "cells": cells,
        "unvisited_counts": list(counts[len(cells) :]),
        "failure": failure,
        "ledger": raw,
        "implemented_diagnostic_passed": (
            failure is None
            and raw["complete"] is True
            and len(cells) == len(counts)
            and all(row["passed"] is True for row in cells)
        ),
        "initial_compilation_observed": False,
        "same_process_service_replacement": True,
        "python_process_restart_tested": False,
        "automatic_workspace_restore_tested": False,
        "headline_timing_eligible": False,
        "qualification_complete": False,
        "pending": [
            "full installed sampling and paired baselines",
            "lost metadata hints",
            "key rotation",
            "expiry fault",
            "first admission fault",
            "Python process restart",
            "matched platform hardware",
        ],
    }
    encode_retained(result)
    return result


def main() -> int:
    from codex_plugin_scanner.guard.native_runtime import native_runtime_status

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--ledger", required=True, type=Path)
    parser.add_argument("--report", required=True, type=Path)
    args = parser.parse_args()
    _clear_proof_overrides()
    status = native_runtime_status()
    if status.identity is None:
        raise RuntimeError("installed native runtime is unavailable")
    args.ledger.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    try:
        result = run(status.identity.path, raw_file=args.ledger)
    except BaseException as error:
        result = {
            "implemented_diagnostic_passed": False,
            "qualification_complete": False,
            "failure": diagnostic_failure(error),
            "complete_report_available": False,
        }
    descriptor = os.open(args.report, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    with os.fdopen(descriptor, "wb") as destination:
        destination.write(encode_retained(result) + b"\n")
        destination.flush()
        os.fsync(destination.fileno())
    print(
        json.dumps(
            {
                "implemented_diagnostic_passed": result["implemented_diagnostic_passed"],
                "qualification_complete": False,
            }
        )
    )
    return 0 if result["implemented_diagnostic_passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Lossless bounded storage for typed poststart observations and native receipts."""

from __future__ import annotations

import hashlib
import json
import math
import os
import re
from pathlib import Path
from typing import Any

from codex_plugin_scanner.guard.native_decision_receipt import validate_native_decision_receipt
from scripts.native_slo_mixed_load import PrivateLedger
from scripts.native_slo_workspace_poststart_session import diagnostic_failure

MAX_PACKET_BYTES = 2 * 1024 * 1024
MAX_PACKETS = 4096
_KEY = re.compile(r"[A-Za-z_][A-Za-z0-9_]{0,95}")
_IDENTIFIER = re.compile(r"[A-Za-z0-9_.:-]{1,512}")
_SENSITIVE = re.compile(r"secret|token|password|private[_-]?key|api[_-]?key", re.IGNORECASE)
_FORBIDDEN_KEYS = frozenset(
    {
        "raw",
        "payload",
        "command",
        "prompt",
        "path",
        "cwd",
        "home",
        "source",
        "content",
        "secret",
        "token",
        "password",
        "output",
        "endpoint",
        "database",
    }
)
_TEXTS = frozenset(
    {
        "owned Python wrapper endpoints including diagnostic overhead",
        "only the complete declared request set, not all daemon traffic",
        "validated SQLite readback time, not transaction commit time",
        "same-host wall-clock observations at wrapper boundaries",
        "caller-side sequential SQL counts and validated getter, not atomic commit time",
        "Actual service state, owned registries and every retained object; not a complete escaped-descendant census.",
        "poststart registration and same-process service replacement on one owned home",
        "bounded Linux poststart workspace observation",
        "ordered checksummed ASCII JSON packets",
        "full installed sampling and paired baselines",
        "lost metadata hints",
        "key rotation",
        "expiry fault",
        "first admission fault",
        "Python process restart",
        "matched platform hardware",
    }
)
_STOP_FIELDS = frozenset(
    {
        "acknowledged",
        "authenticated",
        "generation_present",
        "owner_lock",
        "marker_lock",
        "endpoint",
        "serving_shutdown",
    }
)
_STOP_VALUES = frozenset({"true", "false", "free", "busy", "unverified", "absent", "present", "verified", "unknown"})


def _stop_diagnostic(value: dict[str, Any]) -> None:
    required = {"schema", "operation", "status"} | _STOP_FIELDS
    if set(value) not in (required, required | {"error"}):
        raise ValueError("poststart native stop diagnostic fields invalid")
    if value["operation"] != "resident-stop" or value["status"] not in {
        "contained",
        "already-stopped",
        "failed",
        "contained_client_cleanup_failed",
    }:
        raise ValueError("poststart native stop diagnostic status invalid")
    if any(value[field] not in _STOP_VALUES for field in _STOP_FIELDS):
        raise ValueError("poststart native stop diagnostic evidence invalid")
    if "error" in value and (
        not isinstance(value["error"], str)
        or re.fullmatch(r"native_resident_stop_[a-z0-9_]{1,128}", value["error"]) is None
    ):
        raise ValueError("poststart native stop diagnostic error invalid")


def _validate(value: Any, depth: int, remaining: list[int]) -> None:
    remaining[0] -= 1
    if remaining[0] < 0 or depth > 24:
        raise ValueError("poststart retained structure outside bound")
    if value is None or type(value) is bool:
        return
    if type(value) is int:
        if value.bit_length() > 256:
            raise ValueError("poststart retained integer outside bound")
        return
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("poststart retained clock is not finite")
        return
    if type(value) is str:
        if value not in _TEXTS and (_IDENTIFIER.fullmatch(value) is None or _SENSITIVE.search(value)):
            raise ValueError("poststart retained text is not a declared identifier")
        return
    if type(value) is dict:
        if len(value) > 256:
            raise ValueError("poststart retained mapping outside bound")
        if value.get("schema") == "guard-native-hook-decision-receipt.v1":
            if validate_native_decision_receipt(value) != value:
                raise ValueError("poststart complete receipt identity invalid")
            return
        if value.get("schema") == "hol-guard.native-resident-stop-diagnostic.v1":
            _stop_diagnostic(value)
            return
        for key, child in value.items():
            if type(key) is not str or _KEY.fullmatch(key) is None or key in _FORBIDDEN_KEYS:
                raise ValueError("poststart retained field is not admitted")
            _validate(child, depth + 1, remaining)
        return
    if type(value) in (list, tuple):
        if len(value) > 512:
            raise ValueError("poststart retained sequence outside bound")
        for child in value:
            _validate(child, depth + 1, remaining)
        return
    raise ValueError("poststart retained object has an unsupported type")


def encode_retained(value: Any) -> bytes:
    """Preserve each admitted field and value; never redact or truncate a record."""

    _validate(value, 0, [131072])
    raw = json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("ascii")
    if not 0 < len(raw) <= MAX_PACKET_BYTES:
        raise ValueError("poststart retained packet exceeded its fixed bound")
    return raw


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("poststart retained JSON has duplicate fields")
        result[key] = value
    return result


def _parse(raw: bytes) -> Any:
    return json.loads(raw, object_pairs_hook=_unique_object)


class RetainedLedger:
    """Preserve full objects through the unchanged 8 KiB underlying row limit."""

    def __init__(self, path: Path) -> None:
        self.path = path
        self.original = PrivateLedger(path)
        identity = os.fstat(self.original._stream.fileno())
        self.identity = (identity.st_dev, identity.st_ino)
        self.expected: list[dict[str, Any]] = []
        self.errors: list[dict[str, Any]] = []
        self.finished = False

    def write(self, value: dict[str, Any]) -> bool:
        if self.finished:
            raise RuntimeError("poststart ledger is already finished")
        if self.errors:
            return False
        try:
            raw = encode_retained(value)
            if len(self.expected) >= MAX_PACKETS:
                raise ValueError("poststart retained packet count exceeded its fixed bound")
            kind = value["kind"]
            if not isinstance(kind, str) or re.fullmatch(r"poststart_[a-z_]{1,64}", kind) is None:
                raise ValueError("poststart retained packet kind invalid")
            chunks = [raw[offset : offset + 2048].decode("ascii") for offset in range(0, len(raw), 2048)]
            record = {
                "schema": "poststart.workspace.packet.v1",
                "packet": len(self.expected) + 1,
                "packet_kind": kind,
                "bytes": len(raw),
                "sha256": hashlib.sha256(raw).hexdigest(),
                "parts": len(chunks),
            }
            self.expected.append(record)
            self.original.write({"kind": "packet_begin", **record})
            for index, chunk in enumerate(chunks, 1):
                self.original.write({"kind": "packet_part", **record, "part": index, "payload": chunk})
            self.original.write({"kind": "packet_end", **record})
            return True
        except BaseException as error:
            self.errors.append({"stage": "write", "type": type(error).__name__, "failure": diagnostic_failure(error)})
            raise

    def _readback(self, original: dict[str, Any]) -> dict[str, int]:
        descriptor = os.open(self.path, os.O_RDONLY | os.O_NOFOLLOW)
        records = size = packet = 0
        digest = hashlib.sha256()
        with os.fdopen(descriptor, "rb") as stream:
            identity = os.fstat(stream.fileno())
            if (identity.st_dev, identity.st_ino) != self.identity or identity.st_size != original["bytes"]:
                raise ValueError("poststart retained file identity changed")

            def row() -> dict[str, Any] | None:
                nonlocal records, size
                raw = stream.readline(8193)
                if not raw:
                    return None
                if not raw.endswith(b"\n") or len(raw) > 8192 or records >= 350000:
                    raise ValueError("poststart retained row incomplete or oversized")
                records += 1
                size += len(raw)
                if size > 256 * 1024 * 1024:
                    raise ValueError("poststart retained file outside bound")
                digest.update(raw)
                value = _parse(raw)
                if not isinstance(value, dict):
                    raise ValueError("poststart retained row is not a mapping")
                return value

            for expected in self.expected:
                if row() != {"kind": "packet_begin", **expected}:
                    raise ValueError("poststart retained packet begin differs")
                chunks = []
                for index in range(1, expected["parts"] + 1):
                    part = row()
                    if part is None or type(part.get("payload")) is not str:
                        raise ValueError("poststart retained packet part is absent")
                    chunk = part.pop("payload")
                    if part != {"kind": "packet_part", **expected, "part": index} or not 0 < len(chunk) <= 2048:
                        raise ValueError("poststart retained packet part differs")
                    chunks.append(chunk)
                if row() != {"kind": "packet_end", **expected}:
                    raise ValueError("poststart retained packet end differs")
                raw = "".join(chunks).encode("ascii")
                value = _parse(raw)
                if len(raw) != expected["bytes"] or hashlib.sha256(raw).hexdigest() != expected["sha256"]:
                    raise ValueError("poststart retained full packet differs")
                if encode_retained(value) != raw or value["kind"] != expected["packet_kind"]:
                    raise ValueError("poststart retained full object differs")
                packet += 1
            if row() is not None:
                raise ValueError("poststart retained ledger has undeclared rows")
        if records != original["records"] or size != original["bytes"] or digest.hexdigest() != original["sha256"]:
            raise ValueError("poststart retained ledger digest differs")
        return {"packets": packet, "records": records, "bytes": size}

    def finish(self) -> dict[str, Any]:
        if self.finished:
            raise RuntimeError("poststart ledger finish repeated")
        self.finished = True
        result: dict[str, Any] = {
            "complete": False,
            "packets": len(self.expected),
            "errors": self.errors,
            "complete_object_encoding": "ordered checksummed ASCII JSON packets",
            "underlying_record_limit_bytes": 8192,
        }
        try:
            original = self.original.finish()
            result.update(original)
            result["readback"] = self._readback(original)
            result["complete"] = not self.errors
        except BaseException as error:
            self.errors.append(
                {
                    "stage": "finish_or_readback",
                    "type": type(error).__name__,
                    "failure": diagnostic_failure(error),
                }
            )
        return result

"""Attach workspace observers before the real constructor starts its publisher."""

from __future__ import annotations

from collections.abc import Callable, Iterator
from contextlib import ExitStack, contextmanager
from pathlib import Path
from typing import Any
from unittest.mock import patch


@contextmanager
def prepare_owned_publisher(store: Any, prepare: Callable[[Any], None]) -> Iterator[list[Any]]:
    """Forward the production factory and prepare only this exact owned store."""
    from codex_plugin_scanner.guard.daemon import hook_worker

    original = hook_worker.get_native_policy_snapshot_publisher
    captured: list[Any] = []

    def observed(candidate: Any, *args: Any, **kwargs: Any) -> Any:
        publisher = original(candidate, *args, **kwargs)
        if candidate is store:
            if captured:
                raise RuntimeError("workspace construction requested its publisher twice")
            if publisher._thread is not None or publisher._started or publisher.current_snapshot_binding() is not None:
                raise RuntimeError("workspace construction publisher was already started")
            captured.append(publisher)
            prepare(publisher)
        return publisher

    try:
        with patch.object(hook_worker, "get_native_policy_snapshot_publisher", observed):
            yield captured
        if len(captured) != 1:
            raise RuntimeError("workspace construction publisher was not observed")
    except BaseException as error:
        cleanup_error = None
        for publisher in captured:
            try:
                publisher.close()
                if not publisher.closed or (publisher._thread is not None and publisher._thread.is_alive()):
                    raise RuntimeError("workspace constructor publisher containment incomplete")
            except Exception as failure:
                cleanup_error = failure
        if isinstance(error, Exception) and cleanup_error is not None:
            from scripts.native_slo_failure import failure_evidence
            from scripts.native_slo_observation_failure import contextual_failure

            raise contextual_failure(
                error, captured_publisher_contained=False, publisher_cleanup_failure=failure_evidence(cleanup_error)
            ) from error
        raise


def construct_workspace_session(
    runtime: Path,
    *,
    count: int,
    configuration: str | None,
    progress: Callable[[str], None],
    lifetime: ExitStack,
) -> tuple[Any, Any]:
    """Observe construction in the isolated helper without postponing startup."""
    from scripts import native_slo_session
    from scripts.native_slo_workspace_server import WorkspaceScenarioFixture

    original = native_slo_session.GuardDaemonServer
    prepared: list[Any] = []

    def construct(store: Any, *args: Any, **kwargs: Any) -> Any:
        def prepare(publisher: Any) -> None:
            if prepared:
                raise RuntimeError("workspace construction created multiple services")
            fixture = WorkspaceScenarioFixture.before_start(publisher, store.guard_home.parent / "workspace", count)
            prepared.append(fixture)
            lifetime.enter_context(fixture.observer)
            lifetime.callback(fixture.close)

        with prepare_owned_publisher(store, prepare):
            return original(store, *args, **kwargs)

    with patch.object(native_slo_session, "GuardDaemonServer", construct):
        adapter = native_slo_session.AdapterSession(runtime, configuration=configuration, progress=progress)
    try:
        if len(prepared) != 1:
            raise RuntimeError("workspace constructor observation missing")
        fixture = prepared[0]
        fixture.attach(adapter)
        return adapter, fixture
    except BaseException:
        adapter.close()
        raise

