from typing import TYPE_CHECKING, Any, cast

if TYPE_CHECKING:
    from scripts.profile_guard_mcp_fixture import _CHILD, Phases
else:
    from profile_guard_mcp_fixture import _CHILD, Phases


def run_worker(config_path: Path, *, preparation_variant: str) -> int:
    spec = json.loads(config_path.read_text())
    started = time.perf_counter_ns()
    from codex_plugin_scanner.guard import mcp_tool_calls as calls
    from codex_plugin_scanner.guard.adapters.base import HarnessContext
    from codex_plugin_scanner.guard.config import GuardConfig
    from codex_plugin_scanner.guard.proxy import CodexMcpGuardProxy, framing, tool_catalog
    from codex_plugin_scanner.guard.proxy import runtime_mcp as runtime
    from codex_plugin_scanner.guard.store import GuardStore

    imports_ms = (time.perf_counter_ns() - started) / 1e6
    phases = Phases(spec["profile"])
    if preparation_variant not in {"owned", "streaming"}:
        raise ValueError("mcp_benchmark_unknown_preparation_variant")
    native_pilot = None
    preparation_pilot = None
    loaded_adapter_sha256 = None
    pilot_key = f"{preparation_variant}_preparation_pilot"
    if spec.get(pilot_key):
        if preparation_variant == "owned":
            if TYPE_CHECKING:
                from scripts import guard_mcp_owned_preparation_pilot as preparation_adapter
                from scripts.guard_mcp_owned_preparation_pilot import OwnedPreparationPilot
                from scripts.guard_mcp_owned_preparation_pilot import install_adapter as install_preparation_adapter
            else:
                import guard_mcp_owned_preparation_pilot as preparation_adapter
                from guard_mcp_owned_preparation_pilot import OwnedPreparationPilot
                from guard_mcp_owned_preparation_pilot import install_adapter as install_preparation_adapter

            preparation_pilot = OwnedPreparationPilot()
            install_preparation_adapter(runtime, preparation_pilot)
        else:
            if TYPE_CHECKING:
                from scripts import guard_mcp_streaming_preparation_pilot as preparation_adapter
                from scripts.guard_mcp_streaming_preparation_pilot import OwnedPreparationPilot
                from scripts.guard_mcp_streaming_preparation_pilot import install_adapter as install_preparation_adapter
            else:
                import guard_mcp_streaming_preparation_pilot as preparation_adapter
                from guard_mcp_streaming_preparation_pilot import OwnedPreparationPilot
                from guard_mcp_streaming_preparation_pilot import install_adapter as install_preparation_adapter

            loaded_adapter_sha256 = hashlib.sha256(Path(preparation_adapter.__file__).read_bytes()).hexdigest()
            preparation_pilot = OwnedPreparationPilot()
            install_preparation_adapter(runtime, preparation_pilot)
        if spec["profile"]:
            phases.wrap(preparation_pilot, "own_request", "owned_message_snapshot")
            phases.wrap(preparation_adapter, "_exact_binding", "owned_input_binding")
            if preparation_variant == "streaming":
                phases.wrap(preparation_adapter, "_binding_matches", "owned_input_binding")
            phases.wrap(calls, "_build_tool_call_hash_for_categories", "request_identity")
            phases.wrap(calls, "_evaluate_current_tool_call_for_categories", "policy")
            phases.wrap(calls, "_evaluate_tool_call_with_current", "policy")
    if spec.get("native_text_helper"):
        if TYPE_CHECKING:
            from scripts.guard_mcp_text_facts_pilot import TextFactsPilot, install_adapter
        else:
            from guard_mcp_text_facts_pilot import TextFactsPilot, install_adapter

        native_pilot = TextFactsPilot(
            Path(spec["native_text_helper"]),
            minimum_characters=spec["native_minimum_characters"],
        )
        install_adapter(calls, native_pilot)
        if spec["profile"]:
            phases.wrap(native_pilot, "classify", "native_text_ipc")
    if spec["uncached"]:
        runtime._tool_catalog_fingerprint = runtime._uncached_tool_catalog_fingerprint
    if spec["profile"]:
        for name in ("dumps", "loads"):
            phases.wrap(json, name, "serialization")
        phases.wrap(runtime, "_tool_catalog_fingerprint", "catalog_hash")
        phases.wrap(calls, "_tool_call_risk_category_set", "classification")
        if hasattr(calls, "_tool_call_risk_snapshot"):
            phases.wrap(calls, "_tool_call_risk_snapshot", "facts_snapshot")
        phases.wrap(runtime, "evaluate_tool_call", "policy")
        phases.wrap(runtime, "build_tool_call_hash", "request_identity")
        phases.wrap(runtime, "allow_tool_call", "receipt_and_result")
        phases.wrap(runtime, "block_tool_call", "receipt_and_result")

    class MeasuredProxy(CodexMcpGuardProxy):
        def _start_process(self):
            with phases.phase("child_startup"):
                return super()._start_process()

        def _next_child_output_frame(self, *args, **kwargs):
            name = "child_wait" if kwargs.get("required") else "drain_poll"
            if kwargs.get("timeout_seconds") == runtime._TOOLS_CALL_PREWRITE_QUIET_SECONDS:
                name = "prewrite_quiet_barrier"
            with phases.phase(name):
                return super()._next_child_output_frame(*args, **kwargs)

        def _request_inline_approval(self, *args, **kwargs):
            with phases.phase("inline_approval_wait"):
                return super()._request_inline_approval(*args, **kwargs)

        def _write_message(self, *args, **kwargs):
            with phases.phase("pipe_write"):
                return super()._write_message(*args, **kwargs)

        def _capture_tools_catalog(self, *args, **kwargs):
            with phases.phase("catalog_capture"):
                return super()._capture_tools_catalog(*args, **kwargs)

        def _handle_message(self, **kwargs):
            wall, cpu = time.perf_counter_ns(), time.process_time_ns()
            before = phases.snapshot()
            with phases.phase("other_guard"):
                response, event = super()._handle_message(**kwargs)
            if kwargs["message"].get("method") == "tools/call":
                after = phases.snapshot()
                delta = {
                    name: {key: value - before.get(name, {}).get(key, 0) for key, value in values.items()}
                    for name, values in after.items()
                }
                observations.append(
                    {
                        "wall_ms": (time.perf_counter_ns() - wall) / 1e6,
                        "parent_cpu_ms": (time.process_time_ns() - cpu) / 1e6,
                        "phases": delta,
                        "decision": event.get("decision"),
                        "catalog_generation": self._tool_catalog_generation,
                        "catalog_state": self._tool_catalog_state,
                    }
                )
            return response, event

    observations: list[dict[str, Any]] = []
    root = config_path.parent
    home, workspace, guard_home = root / "home", root / "workspace", root / "guard"
    for path in (home, workspace, guard_home):
        path.mkdir()
    context = HarnessContext(home_dir=home, workspace_dir=workspace, guard_home=guard_home)
    config = GuardConfig(
        guard_home=guard_home,
        workspace=workspace,
        default_action="review" if spec["approval"] != "none" else "warn",
        approval_surface_policy="never-auto-open",
    )
    with phases.phase("proxy_construction"):
        proxy = MeasuredProxy(
            server_name="synthetic",
            command=[
                sys.executable,
                "-u",
                "-c",
                _CHILD,
                str(spec["catalog_size"]),
                str(spec["child_delay_ms"] / 1000),
                str(root / "child.json"),
                "true" if spec["compact_result"] else "false",
            ],
            context=context,
            store=GuardStore(guard_home),
            config=config,
            current_config_provider=lambda: config,
            source_scope="project",
            config_path=str(workspace / ".mcp.json"),
        )
    worker_failure = None
    try:
        exit_code = proxy.serve()
    except Exception as error:
        exit_code = 1
        worker_failure = type(error).__name__
    finally:
        if native_pilot is not None:
            native_pilot.close()
    worker_peak_rss_bytes = None
    if sys.platform in {"linux", "darwin"}:
        import resource

        worker_peak_rss_bytes = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * (
            1024 if sys.platform == "linux" else 1
        )
    Path(spec["worker_output"]).write_text(
        json.dumps(
            {
                "imports_ms": imports_ms,
                "observations": observations,
                "all_phases": phases.snapshot(),
                "exit_code": exit_code,
                "worker_failure": worker_failure,
                "native_text_pilot": native_pilot.evidence() if native_pilot is not None else None,
                **{pilot_key: preparation_pilot.evidence() if preparation_pilot is not None else None},
                **({"loaded_adapter_sha256": loaded_adapter_sha256} if preparation_variant == "streaming" else {}),
                "quiet_barrier_seconds": runtime._TOOLS_CALL_PREWRITE_QUIET_SECONDS,
                "worker_peak_rss_bytes": worker_peak_rss_bytes,
                "loaded_runtime_sha256": {
                    name: hashlib.sha256(Path(cast(str, module.__file__)).read_bytes()).hexdigest()
                    for name, module in (
                        ("proxy/runtime_mcp.py", runtime),
                        ("mcp_tool_calls.py", calls),
                        ("proxy/framing.py", framing),
                        ("proxy/tool_catalog.py", tool_catalog),
                    )
                },
            }
        )
    )
    return exit_code


def tree_sample(process: subprocess.Popen[str]) -> dict[str, float]:
    import psutil

    parent = psutil.Process(process.pid)
    members = [parent, *parent.children(recursive=True)]
    rss = uss = cpu = 0.0
    for member in members:
        try:
            memory = member.memory_full_info()
            rss += memory.rss
            uss += memory.uss
            times = member.cpu_times()
            cpu += times.user + times.system
        except psutil.NoSuchProcess:
            continue
    return {"rss_bytes": rss, "uss_bytes": uss, "cpu_ms": cpu * 1000, "processes": len(members)}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--variant", choices=("owned", "streaming"), required=True)
    parser.add_argument("--config", type=Path, required=True)
    args = parser.parse_args()
    return run_worker(args.config, preparation_variant=args.variant)


if __name__ == "__main__":
    raise SystemExit(main())

"""Installer retries and finalization after update admission."""

from __future__ import annotations

from pathlib import Path

from ..adapters.base import HarnessContext
from ..mdm.contracts import ManagedNetworkPolicy
from ..store import GuardStore
from .update_artifact import TrustedWheelArtifact
from .update_subprocess import TrustedUpdateContext


def _execute_update(
    *,
    payload: dict[str, object],
    installer: str,
    dry_run: bool,
    context: HarnessContext | None,
    store: GuardStore | None,
    workspace: str | None,
    now: str | None,
    force_pypi_reinstall: bool,
    include_alpha: bool,
    resolved_guard_home: Path,
    network_policy: ManagedNetworkPolicy,
    requested_wheel_path: Path | None,
    trusted_wheel: TrustedWheelArtifact | None,
    target_version: str | None,
    update_context: TrustedUpdateContext,
    current_version: str,
    command: list[str],
    execution_command: list[str],
    daemon_refresh_required: bool,
) -> tuple[dict[str, object], int]:
    active_command = execution_command
    active_display_command = command
    attempted_force_retry = False

    def finish_update(result: tuple[dict[str, object], int]) -> tuple[dict[str, object], int]:
        return result

    attempted_pipx_recovery = False
    propagation_retries = 0
    installer_execution_started = False
    while True:
        try:
            if trusted_wheel is not None:
                trusted_wheel.revalidate()
            installer_execution_started = True
            result = update_context.run(active_command)
        except _update.UpdateArtifactError as error:
            return finish_update(
                _update._trusted_update_failure(
                    payload,
                    _update.UpdateSubprocessError(error.reason_code),
                    trusted_wheel=trusted_wheel,
                    retain_trusted_wheel=installer_execution_started,
                )
            )
        except _update.UpdateSubprocessError as error:
            return finish_update(
                _update._trusted_update_failure(
                    payload,
                    error,
                    trusted_wheel=trusted_wheel,
                    retain_trusted_wheel=installer_execution_started,
                )
            )
        payload["command"] = active_display_command
        payload["stdout"] = _update._normalize_output_text(result.stdout)
        payload["stderr"] = _update._normalize_output_text(result.stderr)
        payload["return_code"] = result.returncode
        if result.output_limited:
            return finish_update(
                _update._trusted_update_failure(
                    payload,
                    _update.UpdateSubprocessError("update_installer_output_limit"),
                    trusted_wheel=trusted_wheel,
                    retain_trusted_wheel=installer_execution_started,
                )
            )
        _update.importlib.invalidate_caches()
        try:
            payload["resulting_version"] = _update._current_version_from_subprocess(update_context)
        except _update.UpdateSubprocessError as error:
            return finish_update(
                _update._trusted_update_failure(
                    payload,
                    error,
                    trusted_wheel=trusted_wheel,
                    retain_trusted_wheel=installer_execution_started,
                )
            )
        initial_version_check = payload.get("version_check")
        resulting_version = str(payload.get("resulting_version") or current_version)
        if result.returncode != 0:
            installer_output = _update._installer_output_text(payload.get("stdout"), payload.get("stderr"))
            if (
                installer == "pipx"
                and not attempted_pipx_recovery
                and _update._contains_any(installer_output, _update._PIPX_LAUNCHER_FAILURE_HINTS)
            ):
                pip_display_command = _update._update_command(
                    "pip",
                    use_pypi=trusted_wheel is None,
                    target_version=target_version,
                    wheel_path=requested_wheel_path if trusted_wheel is not None else None,
                )
                pip_execution_display_command = _update._update_command(
                    "pip",
                    use_pypi=trusted_wheel is None,
                    target_version=target_version,
                    wheel_path=trusted_wheel.staged_path if trusted_wheel is not None else None,
                )
                try:
                    active_command = update_context.build_python_pip_command(pip_execution_display_command)
                except _update.UpdateSubprocessError as error:
                    return _update._trusted_update_failure(payload, error, trusted_wheel=trusted_wheel)
                attempted_pipx_recovery = True
                active_display_command = pip_display_command
                payload["installer_recovery"] = "trusted_python_pip"
                continue
            if requested_wheel_path is None and _update._is_pypi_propagation_failure(installer_output):
                if propagation_retries < _update._PYPI_PROPAGATION_RETRY_LIMIT:
                    propagation_retries += 1
                    payload["propagation_retries"] = propagation_retries
                    _update.time.sleep(_update._PYPI_PROPAGATION_RETRY_DELAY_SECONDS)
                    continue
                payload["status"] = "deferred"
                payload["changed"] = False
                payload["reason_code"] = "update_release_propagating"
                payload["message"] = (
                    "The newest HOL Guard release is still reaching PyPI. "
                    "Your current installation remains active; try the update again shortly."
                )
                payload.pop("retry_command", None)
                return payload, 0
            conflict_message = _update._dependency_conflict_message(
                installer_output,
            )
            if conflict_message:
                payload["status"] = "blocked"
                payload["changed"] = False
                payload["dependency_conflict"] = True
                payload["message"] = conflict_message
                payload.pop("retry_command", None)
                if trusted_wheel is not None:
                    _update._retain_local_wheel_staging(payload)
                return finish_update((payload, 1))
            payload["status"] = "failed"
            payload["changed"] = False
            payload["reason_code"] = "update_installer_failed"
            payload["message"] = "HOL Guard update failed."
            if trusted_wheel is not None:
                _update._retain_local_wheel_staging(payload)
            return finish_update((payload, 1))
        if trusted_wheel is not None:
            try:
                if _update.Version(resulting_version) != _update.Version(trusted_wheel.version):
                    return finish_update(
                        _update._trusted_update_failure(
                            payload,
                            _update.UpdateSubprocessError("update_version_mismatch"),
                            trusted_wheel=trusted_wheel,
                            retain_trusted_wheel=installer_execution_started,
                        )
                    )
            except _update.InvalidVersion:
                return finish_update(
                    _update._trusted_update_failure(
                        payload,
                        _update.UpdateSubprocessError("update_version_output_invalid"),
                        trusted_wheel=trusted_wheel,
                        retain_trusted_wheel=installer_execution_started,
                    )
                )
        if trusted_wheel is not None:
            _update._record_verified_local_wheel_receipt(
                payload,
                update_context=update_context,
                trusted_wheel=trusted_wheel,
                guard_home=resolved_guard_home,
                installed_version=resulting_version,
            )
        post_version_check = _update._version_check_payload(
            resulting_version,
            source_kind=update_context.source.public_name,
            network_policy=network_policy,
            include_alpha=include_alpha,
        )
        payload["post_version_check"] = post_version_check
        payload["version_check"] = _update._merge_version_checks(
            initial_version_check,
            post_version_check,
            resulting_version,
        )
        payload["status"] = _update._success_status(payload)
        payload["changed"] = (
            _update._version_changed(current_version, resulting_version) or payload["status"] == "updated"
        )
        if (
            not attempted_force_retry
            and not force_pypi_reinstall
            and requested_wheel_path is None
            and payload.get("status") == "stale"
        ):
            target_version = None
            active_version_check = payload.get("version_check")
            if isinstance(active_version_check, dict):
                latest = active_version_check.get("latest_version")
                if isinstance(latest, str) and latest.strip():
                    target_version = latest.strip()
            retry_command = _update._update_command(installer, use_pypi=True, target_version=target_version)
            if retry_command != active_display_command:
                attempted_force_retry = True
                active_display_command = retry_command
                try:
                    active_command = update_context.build_installer_command(retry_command)
                except _update.UpdateSubprocessError as error:
                    return finish_update(_update._trusted_update_failure(payload, error, trusted_wheel=trusted_wheel))
                payload["upgrade_source"] = update_context.source.public_name
                continue
        break
    conflict_message = _update._dependency_conflict_message(
        _update._installer_output_text(payload.get("stdout"), payload.get("stderr")),
    )
    if payload.get("status") == "stale" and conflict_message:
        payload["status"] = "blocked"
        payload["dependency_conflict"] = True
        payload["message"] = conflict_message
        payload.pop("retry_command", None)
    stale_retry_command = "" if payload.get("status") == "blocked" else _update._stale_retry_command(payload)
    if stale_retry_command:
        payload["retry_command"] = stale_retry_command
    if payload.get("status") != "blocked":
        payload["message"] = _update._success_message(
            status=str(payload["status"]),
            current_version=current_version,
            resulting_version=resulting_version,
            version_check=payload.get("version_check"),
            retry_command=stale_retry_command,
        )
    notes = _update._success_notes(payload)
    if notes:
        payload["notes"] = [*_update._payload_notes(payload), *notes]
    daemon_refresh: dict[str, object] | None = None
    if context is not None:
        daemon_refresh, daemon_refresh_note = _update.refresh_guard_daemon_after_update(
            context,
            update_context=update_context,
            minimum_version=resulting_version,
        )
        if daemon_refresh is not None:
            payload["daemon_refresh"] = daemon_refresh
        _update._append_payload_note(payload, daemon_refresh_note)
    newer_runtime_owns_artifacts = (
        isinstance(daemon_refresh, dict)
        and daemon_refresh.get("status") == "retained_newer_runtime"
        and daemon_refresh.get("runtime_verified") is True
    )
    if newer_runtime_owns_artifacts:
        payload["runtime_artifact_owner"] = "newer_runtime"
        _update._append_payload_note(
            payload,
            "Deferred package shim and harness hook repair to the verified newer runtime.",
        )
    elif payload.get("changed") is True or payload.get("status") == "current":
        package_shims, package_shim_note = _update._refresh_package_shims_after_update(
            context=context,
            dry_run=dry_run,
            update_context=update_context,
        )
        if package_shims is not None:
            payload["package_shims"] = package_shims
        _update._append_payload_note(payload, package_shim_note)
    if not newer_runtime_owns_artifacts:
        repaired_installs, repair_notes = _update._repair_supported_harnesses(
            context=context,
            store=store,
            workspace=workspace,
            now=now,
            dry_run=dry_run,
            update_context=update_context,
        )
        if repair_notes:
            payload["notes"] = [*_update._payload_notes(payload), *repair_notes]
        if repaired_installs:
            payload["managed_installs"] = repaired_installs
            if len(repaired_installs) == 1:
                payload["managed_install"] = repaired_installs[0]
    if context is not None:
        daemon_refresh_succeeded = _update._daemon_refresh_outcome_succeeded(
            daemon_refresh,
            allow_not_running=True,
        )
        if daemon_refresh_required and not daemon_refresh_succeeded:
            payload.update(
                {
                    "status": "failed",
                    "reason_code": "update_daemon_refresh_failed",
                    "message": "HOL Guard was updated, but its daemon could not be restarted safely.",
                }
            )
            return finish_update((payload, 1))
    return finish_update((payload, 0))


